// ═════════════════════════════════════════════════════════════════════════════
// P3 engine slice (10-mcp-tools.md): playback (§3.13), render_frame_at
// (§3.14/§4), engine-backed media ops (§3.1 probe/proxy/transcode), export +
// the async-job tools (§3.15, §6). All engine access goes through the lazy
// [`EngineBridge`] in `handlers/video_jobs.rs` — see that module's docs for
// the shadow-document snapshot bridge and the no-GPU degradation story.
// ═════════════════════════════════════════════════════════════════════════════

/// The engine bridge, or the structured no-GPU degradation error (10 §7:
/// "fails with a clear error rather than blocking the rest of the surface").
/// `EngineUnavailable` extends the §8 taxonomy — §8 has no code for a missing
/// GPU adapter because §2 assumed a GUI-shared `GpuContext`.
pub(crate) fn engine_bridge(state: &AppState) -> Result<&EngineBridge, ToolResult> {
    state.video_engine.bridge().ok_or_else(|| {
        err_code(
            "EngineUnavailable",
            "no GPU adapter available — video-engine-backed tools \
             (playback/render_frame_at/export_sequence) are unavailable on this machine",
        )
    })
}

/// Frame rate + formats + active-format index of a sequence, read from the
/// REAL document (readonly borrow — design rule 5: never locks `history`).
async fn sequence_render_info(
    state: &AppState,
    seq: SequenceId,
) -> Result<
    (
        FrameRate,
        Vec<photonic_core::timeline::SequenceFormat>,
        usize,
    ),
    ToolResult,
> {
    let doc = state.document.lock().await;
    let project = doc
        .timeline
        .as_ref()
        .ok_or_else(|| ToolResult::error("no timeline project"))?;
    let s = project
        .sequences
        .get(&seq)
        .ok_or_else(|| ToolResult::error(format!("sequence {seq} not found")))?;
    Ok((s.frame_rate, s.formats.clone(), s.active_format))
}

/// The status payload every transport tool returns (`EngineStatus`, 02 §1).
fn engine_status_json(status: &photonic_video::EngineStatus) -> serde_json::Value {
    json!({
        "pending_computations":status.pending_computations,
        "computation_errors":status.computation_errors,
        "playhead_ticks": status.playhead.0,
        "playing": status.playing,
        "dropped_frames": status.dropped,
        "cache": {
            "hits": status.cache.hits,
            "misses": status.cache.misses,
            "resident_entries": status.cache.resident_entries,
            "resident_bytes": status.cache.resident_bytes,
        },
        "source_audition":status.source_audition.as_ref().map(|source|json!({"asset_id":source.asset,"start_ticks":source.range.0.0,"end_ticks":source.range.1.0,"playhead_ticks":source.playhead.0,"playing":source.playing,"has_audio":source.has_audio})),
        "source_audition_error":status.source_audition_error,
        "memory": {
            "decoded_ring_bytes":status.memory.decoded_ring_bytes,"decoded_ring_budget_bytes":status.memory.decoded_ring_budget_bytes,
            "upload_bytes":status.memory.upload_bytes,"still_bytes":status.memory.still_bytes,"vector_bytes":status.memory.vector_bytes,
            "graph_bytes":status.memory.graph_bytes,"gpu_cache_bytes":status.memory.gpu_cache_bytes,"gpu_cache_budget_bytes":status.memory.gpu_cache_budget_bytes,
            "raster_jobs":status.memory.raster_jobs,"raster_job_byte_limit":status.memory.raster_job_byte_limit,"pressure":status.memory.pressure,
            "scope":"managed per-session caches; excludes externally retained textures, renderer scratch, FFmpeg and audio internals"
        },
        "readiness": {"requested":status.readiness.requested,"ready":status.readiness.ready,
            "pending_source_builds":status.readiness.pending_source_builds,"pending_rasters":status.readiness.pending_rasters,
            "capacity_limited":status.readiness.capacity_limited,"failed_sources":status.readiness.failed_sources},
        "command_admission":{"pending":status.command_admission.pending,"coalesced":status.command_admission.coalesced,"rejected":status.command_admission.rejected},
        "audio_xruns": status.audio_xruns,
        "doc_revision": status.doc_revision,
        "snapshot_generation": status.snapshot_generation,
        "frames_published": status.frames_published,
        "evaluations": status.evaluations,
        "evaluation_misses": status.evaluation_misses,
        "last_evaluate_micros": status.last_evaluate_micros,
        "buffering": status.buffering,
        "preview_quality": format!("{:?}", status.preview_quality).to_ascii_lowercase(),
        "active_sequence": status.active_sequence,
        "last_error": status.last_error.as_ref().map(|d| json!({
            "code": d.code.as_str(),
            "severity": format!("{:?}", d.severity),
            "message": d.message,
            "consequence": d.consequence,
        })),
    })
}

/// Poll the published status until `pred` holds or `timeout` elapses;
/// returns the last observed status either way (confirmation is best-effort
/// — the engine applies commands within one 2 ms loop tick, but a saturated
/// box may lag; callers report the snapshot rather than fail).
async fn wait_status(
    bridge: &EngineBridge,
    timeout: Duration,
    pred: impl Fn(&photonic_video::EngineStatus) -> bool,
) -> std::sync::Arc<photonic_video::EngineStatus> {
    let deadline = Instant::now() + timeout;
    loop {
        let s = bridge.session().status();
        if pred(&s) || Instant::now() >= deadline {
            return s;
        }
        tokio::time::sleep(Duration::from_millis(2)).await;
    }
}

/// Settle a transport command (seek/step) against the engine the way
/// `render_frame_at` does, so the returned playhead reflects the command just
/// dispatched — never the tick one engine loop behind.
///
/// The old transport predicates read the *published* playhead directly:
/// `seek` accepted `playhead >= t` and `step` accepted `playhead != before`.
/// Both can be satisfied by the **stale pre-command** status, since the engine
/// sets the clock and re-presents on a later loop iteration than the one that
/// published the status the tool first observes. A backward seek is the sharp
/// case — the old (larger) playhead is already `>= t`, so `seek F45` returned
/// the stale `F150` immediately, and a following `get_engine_status` echoed it.
///
/// Instead we wait for a *fresh* frame (newer than `prev`, pointer-compared) at
/// the exact target frame-start `frame_tick` — a stale pre-command frame has
/// the wrong tick and can't satisfy it — then, for a paused command, confirm
/// the published status caught up to `expect` (its store trails the frame store
/// by under one engine loop). On timeout (no media, or a boundary clamp that
/// produces no distinct frame) it reports the latest status unconditionally.
async fn settle_transport(
    bridge: &EngineBridge,
    prev: Option<std::sync::Arc<photonic_video::EngineFrame>>,
    frame_tick: Tick,
    seq: SequenceId,
    expect: Option<Tick>,
    timeout: Duration,
) -> std::sync::Arc<photonic_video::EngineStatus> {
    let deadline = Instant::now() + timeout;
    let produced = bridge
        .wait_fresh_frame(prev, timeout, |f| f.time == frame_tick && f.sequence == seq)
        .await
        .is_some();
    if produced {
        if let Some(exp) = expect {
            let remaining = deadline.saturating_duration_since(Instant::now());
            return wait_status(bridge, remaining, |s| s.playhead == exp).await;
        }
    }
    bridge.session().status()
}

// ─── Playback (10 §3.13) ─────────────────────────────────────────────────────
//
// These mutate **engine/session state only** — never the document, never
// `history` (01 §11: playhead is session state). Dispatch classifies them
// `ToolOutput::readonly` so no checkpoint is scheduled; §3.13's `mutating*`
// is about side-effect semantics, not the checkpoint machinery.

pub async fn play(state: &AppState, args: PlayArgs) -> ToolResult {
    tracing::debug!("tool: play");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    if let Some(seq) = args.sequence_id {
        if let Err(e) = sequence_render_info(state, seq).await {
            return e;
        }
    }
    let _transport = bridge.lock_transport().await;
    bridge.sync(state).await;
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return err_code(
            "EngineBusy",
            "Engine has not synchronized the document snapshot",
        )
        .with_data(json!({"retryable":true,"snapshot_generation":bridge.snapshot_generation()}));
    }
    if let Some(seq) = args.sequence_id {
        bridge.session().send(EngineCmd::SetActiveSequence(seq));
    }
    if !bridge.session().send(EngineCmd::Play) {
        return ToolResult::error("engine session has shut down");
    }
    // Headless boxes with no audio device play on the soft clock (02 §4) —
    // the engine's lazy cpal open falls back internally, so `play` succeeds
    // rather than raising AudioDeviceUnavailable (10 §7's degraded row).
    let status = wait_status(bridge, Duration::from_secs(2), |s| s.playing).await;
    if !status.playing {
        return err_code("TransportNotConfirmed", "Playback did not start within 2s")
            .with_data(engine_status_json(&status));
    }
    ToolResult::text("playback started").with_data(engine_status_json(&status))
}

pub async fn pause(state: &AppState, _args: PauseArgs) -> ToolResult {
    tracing::debug!("tool: pause");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let _transport = bridge.lock_transport().await;
    if !bridge.session().send(EngineCmd::Pause) {
        return ToolResult::error("engine session has shut down");
    }
    let status = wait_status(bridge, Duration::from_secs(2), |s| !s.playing).await;
    ToolResult::text(format!("paused at tick {}", status.playhead.0))
        .with_data(engine_status_json(&status))
}

pub async fn seek(state: &AppState, args: SeekArgs) -> ToolResult {
    tracing::debug!("tool: seek");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let (fr, _, _) = match sequence_render_info(state, args.sequence_id).await {
        Ok(v) => v,
        Err(e) => return e,
    };
    let t = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(fr),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    if t.0 < 0 {
        return err_code("TickOutOfRange", "seek target must be >= 0")
            .with_data(json!({ "min_ticks": 0 }));
    }
    let _transport = bridge.lock_transport().await;
    bridge.sync(state).await;
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return err_code(
            "EngineBusy",
            "Engine has not synchronized the document snapshot",
        )
        .with_data(json!({"retryable":true,"snapshot_generation":bridge.snapshot_generation()}));
    }
    // The engine presents exact frame-start ticks (02 §4); snap the target so
    // the fresh-frame wait matches what will actually be published.
    let snapped = fr.frame_start(fr.frame_at(t));
    let was_playing = bridge.session().status().playing;
    let prev = bridge.session().latest_frame();
    bridge
        .session()
        .send(EngineCmd::SetActiveSequence(args.sequence_id));
    if !bridge.session().send(EngineCmd::Seek(t)) {
        return ToolResult::error("engine session has shut down");
    }
    // Settle against the produced frame (see `settle_transport`): a backward
    // seek used to report the stale pre-seek playhead because it was already
    // `>= t`. Paused ⇒ confirm the clock landed exactly on `t`; playing ⇒ the
    // clock keeps advancing, so the fresh target frame alone proves the seek.
    let status = settle_transport(
        bridge,
        prev,
        snapped,
        args.sequence_id,
        (!was_playing).then_some(t),
        Duration::from_secs(5),
    )
    .await;
    if !was_playing && (status.playhead != t || status.active_sequence != Some(args.sequence_id)) {
        return err_code(
            "TransportNotConfirmed",
            "Engine did not reach the requested seek target",
        )
        .with_data(engine_status_json(&status));
    }
    ToolResult::text(format!("seeked to tick {}", t.0)).with_data(engine_status_json(&status))
}

pub async fn step(state: &AppState, args: StepArgs) -> ToolResult {
    tracing::debug!("tool: step {}", args.frames);
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let _transport = bridge.lock_transport().await;
    bridge.sync(state).await;
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return err_code(
            "EngineBusy",
            "Engine has not synchronized the document snapshot",
        )
        .with_data(json!({"retryable":true,"snapshot_generation":bridge.snapshot_generation()}));
    }
    // Step is relative, so reading a stale `before` would compound into a
    // stale result (the finding's "step responses lagged"). Sample the current
    // status, compute the exact frame the engine will snap to (mirrors
    // `PlaybackController::step`), then wait for that frame + its published
    // playhead via the same fresh-frame discipline `render_frame_at` uses.
    let before_status = bridge.session().status();
    let before = before_status.playhead;
    let prev = bridge.session().latest_frame();
    if !bridge.session().send(EngineCmd::Step(args.frames)) {
        return ToolResult::error("engine session has shut down");
    }
    let status = match before_status.active_sequence {
        // Step always pauses (02 §4); `expected` is frame-aligned, so we can
        // confirm the exact landed tick (including a clamp at frame 0, where
        // the forced re-present of the same frame satisfies the wait at once).
        Some(seq) => match sequence_render_info(state, seq).await {
            Ok((fr, _, _)) => {
                let target_frame = (fr.frame_at(before) + args.frames as i64).max(0);
                let expected = fr.frame_start(target_frame);
                settle_transport(
                    bridge,
                    prev,
                    expected,
                    seq,
                    Some(expected),
                    Duration::from_secs(5),
                )
                .await
            }
            // Sequence vanished from the real doc mid-call — best-effort pause.
            Err(_) => wait_status(bridge, Duration::from_secs(2), |s| !s.playing).await,
        },
        // No active sequence to present against — just confirm the pause.
        None => wait_status(bridge, Duration::from_secs(2), |s| !s.playing).await,
    };
    ToolResult::text(format!(
        "stepped {} frame(s) — playhead at tick {} (paused)",
        args.frames, status.playhead.0
    ))
    .with_data(engine_status_json(&status))
}

pub async fn set_loop_range(state: &AppState, args: SetLoopRangeArgs) -> ToolResult {
    tracing::debug!("tool: set_loop_range");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let (fr, _, _) = match sequence_render_info(state, args.sequence_id).await {
        Ok(v) => v,
        Err(e) => return e,
    };
    let range = match &args.range {
        None => None,
        Some(r) => {
            let start = match resolve_tick(
                r.start_ticks,
                r.start_tc.as_deref(),
                r.start_seconds,
                Some(fr),
            ) {
                Ok(t) => t,
                Err(e) => return e,
            };
            let end = match resolve_tick(r.end_ticks, r.end_tc.as_deref(), r.end_seconds, Some(fr))
            {
                Ok(t) => t,
                Err(e) => return e,
            };
            if end <= start {
                return err_code("TickOutOfRange", "loop end must be after loop start");
            }
            Some((start, end))
        }
    };
    let _transport = bridge.lock_transport().await;
    bridge.sync(state).await;
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return err_code(
            "EngineBusy",
            "Engine has not synchronized the document snapshot",
        )
        .with_data(json!({"retryable":true,"snapshot_generation":bridge.snapshot_generation()}));
    }
    bridge
        .session()
        .send(EngineCmd::SetActiveSequence(args.sequence_id));
    if !bridge.session().send(EngineCmd::SetLoop(range)) {
        return ToolResult::error("engine session has shut down");
    }
    match range {
        Some((s, e)) => ToolResult::text(format!("loop range set to [{}, {})", s.0, e.0))
            .with_data(json!({ "start_ticks": s.0, "end_ticks": e.0 })),
        None => ToolResult::text("loop range cleared"),
    }
}

pub async fn set_proxy_mode(state: &AppState, args: SetProxyModeArgs) -> ToolResult {
    tracing::debug!("tool: set_proxy_mode");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let mode = match args.mode {
        ProxyModeArg::Auto => ProxyMode::Auto,
        ProxyModeArg::ForceProxy => ProxyMode::ForceProxy,
        ProxyModeArg::ForceOriginal => ProxyMode::ForceOriginal,
    };
    let _transport = bridge.lock_transport().await;
    bridge.set_proxy_mode(mode);
    ToolResult::text(format!("proxy mode set to {mode:?}")).with_data(json!({
        "mode": format!("{mode:?}"),
        "note": "Auto and ForceProxy decode generated proxies where present (see generate_proxies), \
                 falling back to originals otherwise; ForceOriginal always decodes originals. \
                 Proxies are never required for correctness (CAP-014)."
    }))
}

pub async fn get_engine_status(state: &AppState, _args: GetEngineStatusArgs) -> ToolResult {
    tracing::debug!("tool: get_engine_status");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let _transport = bridge.lock_transport().await;
    bridge.sync(state).await;
    let synced = bridge.wait_engine_synced(Duration::from_secs(2)).await;
    let status = bridge.session().status();
    let mut data = engine_status_json(&status);
    data["snapshot_synced"] = json!(synced);
    data["media_tools"] = media_toolchain_status();
    {
        let doc = state.document.lock().await;
        if let Some(project) = &doc.timeline {
            if let Some(sequence) = project
                .active_sequence
                .and_then(|id| project.sequences.get(&id))
            {
                data["color_pipeline"] = json!(photonic_video::color::inspect(sequence));
                data["color_inputs"] =
                    json!(photonic_video::color::inspect_inputs(project, sequence));
            }
        }
    }

    if let Some(frame) = bridge.session().latest_frame() {
        data["grading"] = json!({
            "revision": frame.doc_revision,
            "snapshot_generation": frame.snapshot_generation,
            "time_ticks": frame.time.0,
            "sequence": frame.sequence,
            "diagnostics": frame.grading_errors,
            "color_errors": frame.color_errors,
            "pending_computations":frame.pending_computations,
            "subject_matte_used":frame.subject_matte_used,
            "current": frame.doc_revision == status.doc_revision && frame.snapshot_generation == status.snapshot_generation,
        });
    }

    ToolResult::text(format!(
        "playhead {} — {}",
        status.playhead.0,
        if status.playing { "playing" } else { "paused" }
    ))
    .with_data(data)
}

fn media_toolchain_status() -> serde_json::Value {
    match ffmpeg_locate::locate() {
        Ok(tools) => json!({
            "available": true,
            "selection": if std::env::var_os(ffmpeg_locate::FFMPEG_DIR_ENV).is_some() {
                "explicit_directory"
            } else {
                "path"
            },
            "ffmpeg": tools.ffmpeg,
            "ffprobe": tools.ffprobe,
        }),
        Err(error) => json!({
            "available": false,
            "error": error.to_string(),
        }),
    }
}

/// Diagnose a user-supplied FFmpeg installation without starting the renderer.
pub fn get_media_toolchain_status() -> ToolResult {
    let status = media_toolchain_status();
    ToolResult::text(if status["available"] == true {
        "FFmpeg and ffprobe were found together"
    } else {
        "FFmpeg/ffprobe installation is unavailable"
    })
    .with_data(status)
}

// ─── render_frame_at (10 §3.14 / §4) ─────────────────────────────────────────

/// Restore temporary render settings on success, error, or future cancellation.
struct RenderSettingsGuard<'a> {
    session: &'a EngineSession,
    proxy_mode: ProxyMode,
    preview_quality: PreviewQuality,
    scope_tap: Option<ScopeTapPoint>,
}

impl Drop for RenderSettingsGuard<'_> {
    fn drop(&mut self) {
        self.session.send(EngineCmd::SetProxyMode(self.proxy_mode));
        self.session
            .send(EngineCmd::SetPreviewQuality(self.preview_quality));
        if let Some(tap) = self.scope_tap {
            self.session.send(EngineCmd::SetScopeTap(tap));
        }
    }
}

pub async fn render_frame_at(state: &AppState, args: RenderFrameAtArgs) -> ToolResult {
    tracing::debug!("tool: render_frame_at");
    let bridge = match engine_bridge(state) {
        Ok(b) => b,
        Err(e) => return e,
    };
    let expected_revision = state.history.lock().await.revision();
    let seq_id = args.sequence_id;
    let (fr, formats, active_format) = match sequence_render_info(state, seq_id).await {
        Ok(v) => v,
        Err(e) => return e,
    };
    if formats.is_empty() {
        return err_code("NoFormat", "Sequence has no render format");
    }
    if let Some(fi) = args.format_index {
        if fi >= formats.len() {
            return ToolResult::error(format!(
                "format_index {fi} out of range — sequence has {} format(s)",
                formats.len()
            ));
        }
    }
    let format_index = args
        .format_index
        .unwrap_or(active_format)
        .min(formats.len().saturating_sub(1));
    let (w, h) = (
        formats[format_index].width.max(1),
        formats[format_index].height.max(1),
    );
    let t = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(fr),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    if t.0 < 0 {
        return err_code("TickOutOfRange", "render tick must be >= 0")
            .with_data(json!({ "min_ticks": 0 }));
    }
    // The engine presents exact frame-start ticks (02 §4) — snap down.
    let snapped = fr.frame_start(fr.frame_at(t));
    let scale = args.scale.unwrap_or(1.0);
    if !(scale > 0.0 && scale <= 1.0) {
        return ToolResult::error("scale must be in (0, 1]");
    }
    let output_format = args.output_format.unwrap_or_default();
    if u64::from(w) * u64::from(h) > 16_777_216 {
        return err_code("FrameTooLarge", "Frame inspection is limited to 16 million source pixels; use a smaller sequence format");
    }

    let started = Instant::now();
    let _transport = bridge.lock_transport().await;

    bridge
        .sync_with_format(state, Some((seq_id, format_index)))
        .await;
    if bridge.shadow_revision() != expected_revision {
        return err_code("RevisionConflict", "Document changed while preparing the frame; retry inspection").with_data(json!({"actual_revision":bridge.shadow_revision(),"expected_revision":expected_revision}));
    }
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return ToolResult::error("engine did not pick up the document snapshot within 10s");
    }

    // Media choice and processing resolution are independent. Full must use
    // originals AND the full processing canvas, even on a Draft session.
    let _settings = RenderSettingsGuard {
        session: bridge.session(),
        proxy_mode: bridge.proxy_mode(),
        preview_quality: bridge.session().requested_preview_quality(),
        scope_tap: Some(bridge.session().status().scope_tap),
    };
    let (call_mode, call_quality) = match args.quality {
        RenderQualityArg::Preview => (ProxyMode::ForceProxy, PreviewQuality::Draft),
        RenderQualityArg::Full => (ProxyMode::ForceOriginal, PreviewQuality::Full),
    };
    let prev = bridge.session().latest_frame();
    let request_id = bridge.next_inspection_id();
    if !bridge.session().send(EngineCmd::InspectFrame {
        request_id,
        sequence: seq_id,
        time: snapped,
        proxy_mode: call_mode,
        quality: call_quality,
        scope_tap: ScopeTapPoint::Program,
    }) {
        return err_code("EngineBusy", "Engine command queue is full or closed")
            .with_data(json!({"retryable":true}));
    }

    let frame = bridge
        .wait_inspection_frame(prev, Duration::from_secs(30), request_id, |f| {
            f.time == snapped
                && f.sequence == seq_id
                && f.preview_asset.is_none()
                && f.logical_size == (w, h)
                && f.doc_revision == bridge.shadow_revision()
                && f.snapshot_generation == bridge.snapshot_generation()
                && f.inspection_request_id == Some(request_id)
                && f.preview_quality == call_quality
                && f.proxy_mode == call_mode
        })
        .await;
    let frame = match frame {
        Ok(frame) => frame,
        Err(errors) => return err_code("ColorPipelineUnavailable", errors.join("; ")),
    };
    let result = match frame {
        Some(frame) => {
            if !frame.color_errors.is_empty() {
                return err_code("ColorPipelineUnavailable", frame.color_errors.join("; "));
            }
            // Read the LOGICAL region only — EngineFrame textures are padded
            // to the texture pool's 64 px bucket (see photonic-video
            // session.rs::pad_to_pool_bucket); content sits top-left at the
            // sequence-format size.
            let output_size = if output_format == RenderOutputFormatArg::Png {
                (
                    ((w as f64 * scale).round() as u32).clamp(1, w),
                    ((h as f64 * scale).round() as u32).clamp(1, h),
                )
            } else {
                (w, h)
            };
            let readback = std::sync::Arc::clone(&bridge.readback);
            let gpu = bridge.engine().gpu().clone();
            let texture = std::sync::Arc::clone(&frame.texture);
            let output_encoding = frame.output_encoding;
            let mut result = match tokio::task::spawn_blocking(move || {
                let pixels = readback
                    .lock()
                    .map_err(|_| "readback state poisoned".to_string())?
                    .read(&gpu, &texture, (w, h), output_size)?;
                Ok::<_, String>(build_render_result(
                    pixels,
                    output_size.0,
                    output_size.1,
                    if output_format == RenderOutputFormatArg::Png {
                        1.0
                    } else {
                        scale
                    },
                    output_format,
                    output_encoding,
                    snapped,
                    started.elapsed(),
                ))
            })
            .await
            {
                Ok(Ok(result)) => result,
                Ok(Err(error)) => return err_code("ReadbackFailed", error),
                Err(error) => return err_code("ReadbackFailed", error.to_string()),
            };
            if result.is_error != Some(true) {
                let mut data = result.structured_content.take().unwrap_or_default();
                data["sequence_id"] = json!(seq_id);
                data["revision"] = json!(frame.doc_revision);
                data["snapshot_generation"] = json!(frame.snapshot_generation);
                data["inspection_request_id"] = json!(request_id);
                data["format_index"] = json!(format_index);
                data["quality"] = json!(match args.quality {
                    RenderQualityArg::Full => "full",
                    RenderQualityArg::Preview => "preview",
                });
                data["processing_quality"] =
                    json!(format!("{:?}", frame.preview_quality).to_ascii_lowercase());
                data["source_width"] = json!(w);
                data["source_height"] = json!(h);
                data["gpu_downscaled"] = json!(output_size != (w, h));
                data["cached_preview"] = json!(frame.cached_preview);
                data["caption_notes"] = json!(frame.caption_notes);
                data["grading_errors"] = json!(frame
                    .grading_errors
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>());
                data["output_encoding"] = json!(format!("{:?}", frame.output_encoding));
                result = result.with_data(data);
            }
            result
        }
        None => ToolResult::error(
            "engine did not produce the requested frame within 30s — cold-seek decode \
             cost can dominate (see tool description)",
        ),
    };
    result
}

/// Deterministic box downscale on linear premultiplied f32 pixels (fixed
/// iteration order ⇒ byte-stable output for the raw path).
fn box_downscale(src: &[[f32; 4]], w: u32, h: u32, ow: u32, oh: u32) -> Vec<[f32; 4]> {
    let mut out = Vec::with_capacity((ow * oh) as usize);
    for oy in 0..oh {
        let y0 = (oy as u64 * h as u64 / oh as u64) as u32;
        let y1 = (((oy as u64 + 1) * h as u64).div_ceil(oh as u64) as u32).clamp(y0 + 1, h);
        for ox in 0..ow {
            let x0 = (ox as u64 * w as u64 / ow as u64) as u32;
            let x1 = (((ox as u64 + 1) * w as u64).div_ceil(ow as u64) as u32).clamp(x0 + 1, w);
            let mut acc = [0f64; 4];
            for y in y0..y1 {
                for x in x0..x1 {
                    let p = src[(y * w + x) as usize];
                    for (a, c) in acc.iter_mut().zip(p.iter()) {
                        *a += *c as f64;
                    }
                }
            }
            let n = ((y1 - y0) as f64) * ((x1 - x0) as f64);
            out.push([
                (acc[0] / n) as f32,
                (acc[1] / n) as f32,
                (acc[2] / n) as f32,
                (acc[3] / n) as f32,
            ]);
        }
    }
    out
}

/// IEEE 754 binary32 → binary16 bits, round-to-nearest-even. Values read back
/// from an `Rgba16Float` texture are exactly representable, so the raw path
/// round-trips the GPU's own bits.
fn f32_to_f16_bits(f: f32) -> u16 {
    let bits = f.to_bits();
    let sign = ((bits >> 16) & 0x8000) as u16;
    let exp = ((bits >> 23) & 0xff) as i32;
    let frac = bits & 0x007f_ffff;
    if exp == 0xff {
        // Inf / NaN (quietened).
        return sign | 0x7c00 | if frac != 0 { 0x0200 } else { 0 };
    }
    let exp = exp - 127 + 15;
    if exp >= 0x1f {
        return sign | 0x7c00; // overflow → inf
    }
    if exp <= 0 {
        if exp < -10 {
            return sign; // underflow → signed zero
        }
        // Subnormal half.
        let frac = frac | 0x0080_0000;
        let shift = (14 - exp) as u32;
        let mut sub = (frac >> shift) as u16;
        let rem = frac & ((1u32 << shift) - 1);
        let half = 1u32 << (shift - 1);
        if rem > half || (rem == half && (sub & 1) == 1) {
            sub += 1;
        }
        return sign | sub;
    }
    let mut out = sign | ((exp as u16) << 10) | ((frac >> 13) as u16);
    let rem = frac & 0x1fff;
    if rem > 0x1000 || (rem == 0x1000 && (out & 1) == 1) {
        out += 1; // carry may roll into the exponent — correct RNE behavior
    }
    out
}

fn build_render_result(
    pixels: Vec<[f32; 4]>,
    w: u32,
    h: u32,
    scale: f64,
    output_format: RenderOutputFormatArg,
    output_encoding: photonic_video::graph::ir::FrameColorEncoding,
    tick: Tick,
    elapsed: Duration,
) -> ToolResult {
    let ow = ((w as f64 * scale).round() as u32).clamp(1, w);
    let oh = ((h as f64 * scale).round() as u32).clamp(1, h);
    let pixels = if (ow, oh) == (w, h) {
        pixels
    } else {
        box_downscale(&pixels, w, h, ow, oh)
    };
    let render_ms = elapsed.as_millis() as u64;
    match output_format {
        RenderOutputFormatArg::Png => {
            // The engine publishes either legacy linear or display-encoded
            // pixels. Applying the legacy OETF to the latter changes the look.
            let flat = pixels.into_flattened();
            let planes = match output_encoding {
                photonic_video::graph::ir::FrameColorEncoding::LegacyLinearRec709 => {
                    export_convert::working_frame_to_rgba8(&flat, ow, oh)
                }
                photonic_video::graph::ir::FrameColorEncoding::SrgbDisplay => {
                    export_convert::srgb_display_frame_to_rgba8(&flat, ow, oh)
                }
                _ => {
                    return ToolResult::error(
                        "PNG rendering requires legacy linear or sRGB display output",
                    )
                }
            };
            let rgba8 = match planes {
                export_convert::EncodePlanes::Rgba8 { rgba, .. } => rgba,
                _ => return ToolResult::error("internal error: unexpected plane kind"),
            };
            let Some(img) = image::RgbaImage::from_raw(ow, oh, rgba8) else {
                return ToolResult::error("internal error: pixel buffer size mismatch");
            };
            let mut png = Vec::new();
            if let Err(e) =
                img.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
            {
                return ToolResult::error(format!("PNG encode failed: {e}"));
            }
            ToolResult::text(format!(
                "rendered {ow}x{oh} frame at tick {} ({render_ms} ms)",
                tick.0
            ))
            .with_image(general_purpose::STANDARD.encode(&png))
            .with_data(json!({
                "width": ow, "height": oh, "tick": tick.0,
                "render_ms": render_ms, "output_format": "png",
            }))
        }
        RenderOutputFormatArg::RawRgba16f => {
            let mut bytes = Vec::with_capacity(pixels.len() * 8);
            for px in &pixels {
                for c in px {
                    bytes.extend_from_slice(&f32_to_f16_bits(*c).to_le_bytes());
                }
            }
            ToolResult::text(format!(
                "rendered {ow}x{oh} raw frame at tick {} ({render_ms} ms)",
                tick.0
            ))
            .with_data(json!({
                "width": ow, "height": oh, "tick": tick.0,
                "render_ms": render_ms, "output_format": "raw_rgba16f",
                "encoding": format!("interleaved RGBA, f16 little-endian, row-major, premultiplied; {:?}", output_encoding),
                "data_base64": general_purpose::STANDARD.encode(&bytes),
            }))
        }
    }
}

// ─── Engine-backed media ops (10 §3.1: probe / proxy / transcode) ────────────

/// Resolve an asset to its backing file path, with §8 error mapping.
async fn asset_file_path(
    state: &AppState,
    asset: AssetId,
) -> Result<std::path::PathBuf, ToolResult> {
    let doc = state.document.lock().await;
    let project = doc
        .timeline
        .as_ref()
        .ok_or_else(|| ToolResult::error("no timeline project"))?;
    let a = project
        .media
        .assets
        .get(&asset)
        .ok_or_else(|| ToolResult::error(format!("asset {asset} not found")))?;
    match &a.source {
        photonic_core::timeline::AssetSource::File { path, .. } => Ok(path.clone()),
        _ => Err(ToolResult::error(
            "asset is not file-backed — nothing to probe/transcode",
        )),
    }
}

pub async fn probe_media(state: &AppState, args: ProbeMediaArgs) -> ToolResult {
    tracing::debug!("tool: probe_media {}", args.asset_id);
    let path = match asset_file_path(state, args.asset_id).await {
        Ok(p) => p,
        Err(e) => return e,
    };
    if !path.exists() {
        return err_code(
            "AssetOffline",
            format!("file not found: {}", path.display()),
        );
    }
    let tools = match ffmpeg_locate::locate() {
        Ok(t) => t,
        Err(e) => {
            return err_code(
                "FfmpegUnavailable",
                format!("ffprobe not found ({e}) — set PHOTONIC_FFMPEG_DIR or install ffmpeg"),
            )
        }
    };
    let (job_id, cancel) = match state.video_jobs.lock().expect("job registry poisoned").start("probe_media") {
        Ok(job) => job,
        Err(error) => return ToolResult::error_with_code("JobCapacityExceeded", error.to_string()).with_data(json!({"retryable":true,"max_active_jobs":crate::handlers::video_jobs::MAX_ACTIVE_JOBS})),
    };
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    let document = std::sync::Arc::clone(&state.document);
    let history = std::sync::Arc::clone(&state.history);
    let asset_id = args.asset_id;
    std::thread::spawn(move || {
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Running {
                progress: 0.0,
                message: "probing".into(),
            },
        );
        if cancel.load(Ordering::Relaxed) {
            set_job_status(&jobs, job_id, JobStatus::Cancelled);
            return;
        }
        let before_hash = match video_probe::full_content_hash(&path) {
            Ok(hash) => hash,
            Err(error) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "ProbeFailed".into(),
                        message: format!("cannot identify source before probing: {error}"),
                    },
                );
                return;
            }
        };
        let probe = match video_probe::probe_asset(&tools, &path) {
            Ok(p) => p,
            Err(e) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "ProbeFailed".into(),
                        message: e.to_string(),
                    },
                );
                return;
            }
        };
        // Keep the persisted relink identity in its existing sampled format.
        let hash = match video_probe::content_hash(&path) {
            Ok(hash) => hash,
            Err(error) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "ProbeFailed".into(),
                        message: format!("cannot identify source after probing: {error}"),
                    },
                );
                return;
            }
        };
        match video_probe::full_content_hash(&path) {
            Ok(hash) if hash == before_hash => {}
            Ok(_) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "SourceChangedDuringProbe".into(),
                        message: "source bytes changed while probing; retry probe_media".into(),
                    },
                );
                return;
            }
            Err(error) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "ProbeFailed".into(),
                        message: format!("cannot identify source after probing: {error}"),
                    },
                );
                return;
            }
        }
        // Job completion happens outside dispatch's mutation hook. Use the
        // same undoable command as GUI probing so history revision advances
        // and the MCP engine bridge refreshes its project snapshot.
        if cancel.load(Ordering::Relaxed) {
            set_job_status(&jobs, job_id, JobStatus::Cancelled);
            return;
        }
        let updated = commit_asset_probe(&document, &history, asset_id, &path, &probe, &hash);
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Done {
                result: json!({
                    "asset_id": asset_id,
                    "updated": updated,
                    "probe": probe,
                    "content_hash": hash,
                }),
            },
        );
    });
    ToolResult::text("probe job started — poll get_job_status")
        .with_data(json!({ "job_id": job_id }))
}

/// Only the source that was probed may receive the result. A relink or removal
/// during the worker's lifetime leaves the new asset metadata untouched.
fn commit_asset_probe(
    document: &std::sync::Arc<tokio::sync::Mutex<photonic_core::Document>>,
    history: &std::sync::Arc<tokio::sync::Mutex<photonic_core::history::CommandHistory>>,
    asset_id: AssetId,
    expected_path: &std::path::Path,
    probe: &photonic_core::timeline::MediaProbe,
    hash: &str,
) -> bool {
    let mut doc = document.blocking_lock();
    let cmd = doc.timeline.as_ref().and_then(|p| {
        let asset = p.media.assets.get(&asset_id)?;
        match &asset.source {
            photonic_core::timeline::AssetSource::File { path, .. } if path == expected_path => {}
            _ => return None,
        }
        ops::set_asset_meta(p, asset_id, Some(probe.clone()), Some(hash.to_owned())).ok()
    });
    if let Some(cmd) = cmd {
        let mut hist = history.blocking_lock();
        hist.execute_discrete(Command::Timeline(cmd), &mut doc);
        hist.schedule_mcp_checkpoint("probe_media");
        true
    } else {
        false
    }
}

/// Commit a proxy status transition through history so the engine bridge sees
/// the new revision. Lock order is document before history.
/// Returns whether the asset still existed.
fn set_asset_proxy(
    document: &std::sync::Arc<tokio::sync::Mutex<photonic_core::Document>>,
    history: &std::sync::Arc<tokio::sync::Mutex<photonic_core::history::CommandHistory>>,
    asset_id: AssetId,
    expected_source: &std::path::Path,
    expected_current: Option<&ProxyRef>,
    proxy: Option<ProxyRef>,
    checkpoint: &str,
) -> bool {
    let mut doc = document.blocking_lock();
    let cmd = doc.timeline.as_ref().and_then(|p| {
        let asset = p.media.assets.get(&asset_id)?;
        match &asset.source {
            photonic_core::timeline::AssetSource::File { path, .. } if path == expected_source => {}
            _ => return None,
        }
        if asset
            .proxy
            .as_ref()
            .is_some_and(|current| current.origin == photonic_core::timeline::ProxyOrigin::Attached)
            || expected_current.is_some_and(|expected| asset.proxy.as_ref() != Some(expected))
        {
            return None;
        }
        ops::set_asset_proxy(p, asset_id, proxy).ok()
    });
    if let Some(cmd) = cmd {
        let mut hist = history.blocking_lock();
        hist.execute_discrete(Command::Timeline(cmd), &mut doc);
        hist.schedule_mcp_checkpoint(checkpoint.to_string());
        true
    } else {
        false // asset removed while generating
    }
}

pub async fn generate_proxies(state: &AppState, args: GenerateProxiesArgs) -> ToolResult {
    tracing::debug!("tool: generate_proxies ({} asset(s))", args.asset_ids.len());
    if args.asset_ids.is_empty() {
        return ToolResult::error("no asset_ids given");
    }
    let tools = match ffmpeg_locate::locate() {
        Ok(t) => t,
        Err(e) => {
            return err_code(
                "FfmpegUnavailable",
                format!("ffmpeg not found ({e}) — set PHOTONIC_FFMPEG_DIR or install ffmpeg"),
            )
        }
    };
    let force = args.force.unwrap_or(false);

    // Resolve each asset to a file-backed video path under the doc lock. A
    // fresh content hash is computed by the worker; persisted hashes may be
    // stale after an external file replacement. Non-video, embedded,
    // and unknown assets are skipped with a reason (never an error — a batch
    // proxies what it can).
    let mut work: Vec<(AssetId, std::path::PathBuf)> = Vec::new();
    let mut skipped: Vec<serde_json::Value> = Vec::new();
    {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        for id in &args.asset_ids {
            match project.media.assets.get(id) {
                None => skipped.push(json!({ "asset_id": id, "reason": "not found" })),
                Some(a) if a.kind != AssetKind::Video => {
                    skipped.push(json!({ "asset_id": id, "reason": "not a video asset" }))
                }
                // G-15A: never replace a user-attached proxy via generate_proxies.
                Some(a)
                    if a.proxy.as_ref().is_some_and(|p| {
                        p.origin == photonic_core::timeline::ProxyOrigin::Attached
                    }) =>
                {
                    skipped.push(json!({
                        "asset_id": id,
                        "reason": "attached proxy present (detach first)"
                    }))
                }
                Some(a) => match &a.source {
                    photonic_core::timeline::AssetSource::File { path, .. } => {
                        work.push((*id, path.clone()))
                    }
                    _ => skipped.push(json!({ "asset_id": id, "reason": "not file-backed" })),
                },
            }
        }
    }
    if work.is_empty() {
        return err_code("NoWorkableAssets", "no file-backed video assets to proxy")
            .with_data(json!({ "skipped": skipped }));
    }

    let (job_id, cancel) = match state.video_jobs.lock().expect("job registry poisoned").start("generate_proxies") {
        Ok(job) => job,
        Err(error) => return ToolResult::error_with_code("JobCapacityExceeded", error.to_string()).with_data(json!({"retryable":true,"max_active_jobs":crate::handlers::video_jobs::MAX_ACTIVE_JOBS})),
    };
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    let document = std::sync::Arc::clone(&state.document);
    let history = std::sync::Arc::clone(&state.history);
    let skipped_ret = skipped.clone();
    let total = work.len();

    std::thread::spawn(move || {
        let cancel_fn = || cancel.load(Ordering::Relaxed);
        let mut results: Vec<serde_json::Value> = Vec::new();
        for (i, (asset_id, input)) in work.into_iter().enumerate() {
            if cancel.load(Ordering::Relaxed) {
                set_job_status(&jobs, job_id, JobStatus::Cancelled);
                return;
            }
            set_job_status(
                &jobs,
                job_id,
                JobStatus::Running {
                    progress: i as f32 / total as f32,
                    message: format!("proxy {}/{}", i + 1, total),
                },
            );

            if !input.exists() {
                results.push(json!({
                    "asset_id": asset_id, "status": "failed", "error": "source offline"
                }));
                continue;
            }
            let full_hash = match video_probe::full_content_hash(&input) {
                Ok(hash) => hash,
                Err(error) => {
                    results.push(json!({
                        "asset_id": asset_id, "status": "failed",
                        "error": format!("source identity: {error}")
                    }));
                    continue;
                }
            };
            // The cache key must identify the bytes being transcoded, even
            // if the project still has an older import/probe hash.
            let hash = match video_probe::content_hash(&input) {
                Ok(h) => h,
                Err(e) => {
                    results.push(json!({
                        "asset_id": asset_id, "status": "failed",
                        "error": format!("content hash: {e}")
                    }));
                    continue;
                }
            };
            let cache_dir = video_proxy::proxy_cache_dir(None);
            let out = video_proxy::proxy_cache_path(&cache_dir, &hash);

            // Reuse an existing cached proxy unless the caller forces a rebuild.
            if out.is_file() && !force {
                if !matches!(video_probe::full_content_hash(&input), Ok(ref current) if current == &full_hash)
                {
                    results.push(json!({
                        "asset_id": asset_id, "status": "failed",
                        "error": "source changed while selecting cached proxy"
                    }));
                    continue;
                }
                let updated = set_asset_proxy(
                    &document,
                    &history,
                    asset_id,
                    &input,
                    None,
                    Some(ProxyRef::ready_generated(out.clone())),
                    "generate_proxies",
                );
                results.push(json!({
                    "asset_id": asset_id,
                    "status": if updated { "ready" } else { "skipped" },
                    "reused": true, "path": out
                }));
                continue;
            }

            // Mark Pending so proxy_status reflects reality mid-flight, then
            // transcode → Ready / Failed.
            let pending = ProxyRef::with_status(out.clone(), ProxyStatus::Pending);
            if !set_asset_proxy(
                &document,
                &history,
                asset_id,
                &input,
                None,
                Some(pending.clone()),
                "generate_proxies",
            ) {
                results.push(json!({
                    "asset_id": asset_id, "status": "skipped",
                    "reason": "asset source or proxy changed during job"
                }));
                continue;
            }
            let source_is_current = || matches!(video_probe::full_content_hash(&input), Ok(ref current) if current == &full_hash);
            match video_proxy::generate_proxy_checked(
                &tools,
                &input,
                &out,
                &cancel_fn,
                &source_is_current,
            ) {
                Ok(()) => {
                    if !source_is_current() {
                        // The source changed in the narrow window after the
                        // pre-publish check. Do not leave an invalid cache hit.
                        let _ = std::fs::remove_file(&out);
                        set_asset_proxy(
                            &document,
                            &history,
                            asset_id,
                            &input,
                            Some(&pending),
                            Some(ProxyRef::with_status(out.clone(), ProxyStatus::Failed)),
                            "generate_proxies",
                        );
                        results.push(json!({
                            "asset_id": asset_id, "status": "failed",
                            "error": "source changed during proxy generation"
                        }));
                        continue;
                    }
                    let updated = set_asset_proxy(
                        &document,
                        &history,
                        asset_id,
                        &input,
                        Some(&pending),
                        Some(ProxyRef::ready_generated(out.clone())),
                        "generate_proxies",
                    );
                    results.push(json!({
                        "asset_id": asset_id,
                        "status": if updated { "ready" } else { "skipped" },
                        "path": out
                    }));
                }
                Err(video_proxy::ProxyError::Cancelled) => {
                    set_asset_proxy(
                        &document,
                        &history,
                        asset_id,
                        &input,
                        Some(&pending),
                        Some(ProxyRef::with_status(out.clone(), ProxyStatus::Failed)),
                        "generate_proxies",
                    );
                    set_job_status(&jobs, job_id, JobStatus::Cancelled);
                    return;
                }
                Err(e) => {
                    set_asset_proxy(
                        &document,
                        &history,
                        asset_id,
                        &input,
                        Some(&pending),
                        Some(ProxyRef::with_status(out.clone(), ProxyStatus::Failed)),
                        "generate_proxies",
                    );
                    results.push(json!({
                        "asset_id": asset_id, "status": "failed", "error": e.to_string()
                    }));
                }
            }
        }
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Done {
                result: json!({ "proxies": results, "skipped": skipped }),
            },
        );
    });

    ToolResult::text(format!(
        "proxy generation started for {total} asset(s) — poll get_job_status"
    ))
    .with_data(json!({ "job_id": job_id, "skipped": skipped_ret }))
}

pub async fn remove_proxy(state: &AppState, args: RemoveProxyArgs) -> ToolResult {
    tracing::debug!("tool: remove_proxy ({} asset(s))", args.asset_ids.len());
    if args.asset_ids.is_empty() {
        return ToolResult::error("no asset_ids given");
    }
    // Detach references through history. Cache files stay in place so undo
    // can restore a usable proxy; cache eviction is a separate operation.
    let mut assets: Vec<serde_json::Value> = Vec::new();
    {
        let mut doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let mut commands = Vec::new();
        for id in &args.asset_ids {
            match project.media.assets.get(id) {
                Some(a) => match &a.proxy {
                    Some(p) => {
                        let origin = match p.origin {
                            photonic_core::timeline::ProxyOrigin::Generated => "generated",
                            photonic_core::timeline::ProxyOrigin::Attached => "attached",
                        };
                        commands
                            .push(ops::set_asset_proxy(project, *id, None).expect("asset exists"));
                        assets.push(json!({
                            "asset_id": id,
                            "removed": true,
                            "path": p.path,
                            "origin": origin,
                        }));
                    }
                    None => assets
                        .push(json!({ "asset_id": id, "removed": false, "reason": "no proxy" })),
                },
                None => {
                    assets.push(json!({ "asset_id": id, "removed": false, "reason": "not found" }))
                }
            }
        }
        if !commands.is_empty() {
            let mut hist = state.history.lock().await;
            hist.execute_discrete(batch_or_single(commands), &mut doc);
            hist.schedule_mcp_checkpoint("remove_proxy");
        }
    }
    let detached = assets
        .iter()
        .filter(|a| a.get("removed") == Some(&json!(true)))
        .count();
    ToolResult::text(format!("detached {detached} proxy ref(s)"))
        .with_data(json!({ "assets": assets, "files_deleted": 0 }))
}

/// Attach a user-supplied proxy file to a video asset (G-15A). Never copies
/// the file; validation via ffprobe. Detach never deletes attached files.
pub async fn attach_proxy(state: &AppState, args: AttachProxyArgs) -> ToolResult {
    tracing::debug!("tool: attach_proxy asset={}", args.asset_id);
    let tools = match ffmpeg_locate::locate() {
        Ok(t) => t,
        Err(e) => {
            return err_code(
                "FfmpegUnavailable",
                format!("ffmpeg not found ({e}) — set PHOTONIC_FFMPEG_DIR or install ffmpeg"),
            )
        }
    };
    let allow_mismatch = args.allow_mismatch.unwrap_or(false);
    let proxy_path = std::path::PathBuf::from(&args.path);

    let original = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some(asset) = project.media.assets.get(&args.asset_id) else {
            return err_code("NotFound", format!("asset {} not found", args.asset_id));
        };
        if asset.kind != AssetKind::Video {
            return err_code("NotVideo", "attach_proxy requires a video asset");
        }
        match &asset.source {
            photonic_core::timeline::AssetSource::File { path, .. } => path.clone(),
            _ => return err_code("NotFileBacked", "attach_proxy requires a file-backed asset"),
        }
    };

    let validation =
        match video_proxy::validate_attach(&tools, &original, &proxy_path, allow_mismatch) {
            Ok(v) => v,
            Err(e) => {
                return err_code(
                    match &e {
                        video_proxy::AttachError::MissingPath(_) => "MissingPath",
                        video_proxy::AttachError::NotAFile(_) => "NotAFile",
                        video_proxy::AttachError::SameAsOriginal => "SameAsOriginal",
                        video_proxy::AttachError::NotVideo => "NotVideo",
                        video_proxy::AttachError::ProbeFailed(_) => "ProbeFailed",
                        video_proxy::AttachError::DurationMismatch => "DurationMismatch",
                        video_proxy::AttachError::FrameRateMismatch => "FrameRateMismatch",
                    },
                    e.to_string(),
                )
            }
        };

    {
        let mut doc = state.document.lock().await;
        let Some(asset) = doc
            .timeline
            .as_mut()
            .and_then(|p| p.media.assets.get_mut(&args.asset_id))
        else {
            return err_code("NotFound", format!("asset {} not found", args.asset_id));
        };
        asset.proxy = Some(validation.proxy.clone());
    }
    {
        let mut hist = state.history.lock().await;
        hist.schedule_mcp_checkpoint("attach_proxy".to_string());
    }
    ToolResult::text("proxy attached").with_data(json!({
        "asset_id": args.asset_id,
        "path": validation.proxy.path,
        "origin": "attached",
        "warnings": validation.warnings,
    }))
}

/// Detach proxy without deleting user-owned Attached files (G-15A).
pub async fn detach_proxy(state: &AppState, args: DetachProxyArgs) -> ToolResult {
    tracing::debug!("tool: detach_proxy asset={}", args.asset_id);
    let (had, origin, path) = {
        let mut doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_mut() else {
            return ToolResult::error("no timeline project");
        };
        match project.media.assets.get_mut(&args.asset_id) {
            Some(a) => match a.proxy.take() {
                Some(p) => (
                    true,
                    match p.origin {
                        photonic_core::timeline::ProxyOrigin::Generated => "generated",
                        photonic_core::timeline::ProxyOrigin::Attached => "attached",
                    },
                    Some(p.path),
                ),
                None => (false, "none", None),
            },
            None => return err_code("NotFound", format!("asset {} not found", args.asset_id)),
        }
    };
    if had {
        let mut hist = state.history.lock().await;
        hist.schedule_mcp_checkpoint("detach_proxy");
    }
    ToolResult::text(if had {
        "proxy detached (file not deleted)"
    } else {
        "no proxy to detach"
    })
    .with_data(json!({
        "asset_id": args.asset_id,
        "detached": had,
        "origin": origin,
        "path": path,
        "file_deleted": false,
    }))
}

impl TranscodePresetArg {
    /// ffmpeg encode args + output extension for each editing-intermediate
    /// preset (10 §3.1: user-picked codec, distinct from the proxy profile).
    fn ffmpeg_spec(self) -> (&'static [&'static str], &'static str, &'static str) {
        match self {
            TranscodePresetArg::ProresProxy => (
                &[
                    "-c:v",
                    "prores_ks",
                    "-profile:v",
                    "0",
                    "-vendor",
                    "apl0",
                    "-pix_fmt",
                    "yuv422p10le",
                    "-c:a",
                    "pcm_s16le",
                ],
                "mov",
                "prores_proxy",
            ),
            TranscodePresetArg::ProresLt => (
                &[
                    "-c:v",
                    "prores_ks",
                    "-profile:v",
                    "1",
                    "-vendor",
                    "apl0",
                    "-pix_fmt",
                    "yuv422p10le",
                    "-c:a",
                    "pcm_s16le",
                ],
                "mov",
                "prores_lt",
            ),
            TranscodePresetArg::DnxhrLb => (
                &[
                    "-c:v",
                    "dnxhd",
                    "-profile:v",
                    "dnxhr_lb",
                    "-pix_fmt",
                    "yuv422p",
                    "-c:a",
                    "pcm_s16le",
                ],
                "mov",
                "dnxhr_lb",
            ),
            TranscodePresetArg::H264High => (
                &[
                    "-c:v", "libx264", "-preset", "medium", "-crf", "18", "-pix_fmt", "yuv420p",
                    "-c:a", "aac",
                ],
                "mp4",
                "h264_high",
            ),
        }
    }
}

pub async fn transcode_media(state: &AppState, args: TranscodeMediaArgs) -> ToolResult {
    tracing::debug!("tool: transcode_media {}", args.asset_id);
    let input = match asset_file_path(state, args.asset_id).await {
        Ok(p) => p,
        Err(e) => return e,
    };
    if !input.exists() {
        return err_code(
            "AssetOffline",
            format!("file not found: {}", input.display()),
        );
    }
    let tools = match ffmpeg_locate::locate() {
        Ok(t) => t,
        Err(e) => {
            return err_code(
                "FfmpegUnavailable",
                format!("ffmpeg not found ({e}) — set PHOTONIC_FFMPEG_DIR or install ffmpeg"),
            )
        }
    };
    let (enc_args, ext, preset_name) = args.preset.ffmpeg_spec();
    let out_path = match &args.out_path {
        Some(p) => {
            match crate::path_guard::check_path(state, p, photonic_core::PathAccess::Write) {
                Ok(path) => path,
                Err(e) => return e,
            }
        }
        None => {
            let p = input.with_extension(format!("{preset_name}.{ext}"));
            match crate::path_guard::check_path(state, &p, photonic_core::PathAccess::Write) {
                Ok(path) => path,
                Err(e) => return e,
            }
        }
    };
    if out_path == input {
        return ToolResult::error("out_path must differ from the source file");
    }
    let (job_id, cancel) = match state.video_jobs.lock().expect("job registry poisoned").start("transcode_media") {
        Ok(job) => job,
        Err(error) => return ToolResult::error_with_code("JobCapacityExceeded", error.to_string()).with_data(json!({"retryable":true,"max_active_jobs":crate::handlers::video_jobs::MAX_ACTIVE_JOBS})),
    };
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    let out_clone = out_path.clone();
    std::thread::spawn(move || {
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Running {
                progress: 0.0,
                message: format!("transcoding to {preset_name}"),
            },
        );
        let mut cmd = std::process::Command::new(&tools.ffmpeg);
        cmd.arg("-y")
            .args(["-nostdin", "-loglevel", "error"])
            .arg("-i")
            .arg(&input)
            .args(enc_args)
            .arg(&out_clone)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped());
        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "TranscodeFailed".into(),
                        message: format!("spawn ffmpeg: {e}"),
                    },
                );
                return;
            }
        };
        // Poll for exit / cooperative cancel (kill + clean the partial file).
        let status = loop {
            if cancel.load(Ordering::Relaxed) {
                let _ = child.kill();
                let _ = child.wait();
                let _ = std::fs::remove_file(&out_clone);
                set_job_status(&jobs, job_id, JobStatus::Cancelled);
                return;
            }
            match child.try_wait() {
                Ok(Some(status)) => break status,
                Ok(None) => std::thread::sleep(Duration::from_millis(100)),
                Err(e) => {
                    set_job_status(
                        &jobs,
                        job_id,
                        JobStatus::Failed {
                            error_code: "TranscodeFailed".into(),
                            message: format!("wait ffmpeg: {e}"),
                        },
                    );
                    return;
                }
            }
        };
        if status.success() {
            set_job_status(
                &jobs,
                job_id,
                JobStatus::Done {
                    result: json!({ "output_path": out_clone, "preset": preset_name }),
                },
            );
        } else {
            let mut stderr = String::new();
            if let Some(mut s) = child.stderr.take() {
                use std::io::Read;
                let _ = s.read_to_string(&mut stderr);
            }
            let tail: String = stderr
                .chars()
                .rev()
                .take(500)
                .collect::<Vec<_>>()
                .into_iter()
                .rev()
                .collect();
            set_job_status(
                &jobs,
                job_id,
                JobStatus::Failed {
                    error_code: "TranscodeFailed".into(),
                    message: format!("ffmpeg exited with {status}: {tail}"),
                },
            );
        }
    });
    ToolResult::text(format!(
        "transcode job started → {} — poll get_job_status",
        out_path.display()
    ))
    .with_data(json!({ "job_id": job_id, "output_path": out_path }))
}

// ─── Export (10 §3.15) + job tools (10 §6) ───────────────────────────────────

pub(crate) fn find_export_preset(name: &str) -> Option<export_presets::ExportPreset> {
    export_presets::built_in_presets()
        .into_iter()
        .chain(export_presets::load_custom_presets().unwrap_or_default())
        .find(|p| p.name == name)
}

pub async fn export_sequence(state: &AppState, args: ExportSequenceArgs) -> ToolResult {
    super::video_export::export_sequence(state, args).await
}

pub async fn get_job_status(state: &AppState, args: GetJobStatusArgs) -> ToolResult {
    tracing::debug!("tool: get_job_status {}", args.job_id);
    let payload = state
        .video_jobs
        .lock()
        .expect("job registry poisoned")
        .status_json(args.job_id);
    match payload {
        Some(v) => {
            let s = v["status"]["state"].as_str().unwrap_or("?").to_string();
            ToolResult::text(format!("job {} — {s}", args.job_id)).with_data(v)
        }
        None => err_code(
            "JobNotFound",
            format!(
                "job {} unknown or evicted (terminal jobs are retained 10 minutes)",
                args.job_id
            ),
        ),
    }
}

pub async fn cancel_job(state: &AppState, args: CancelJobArgs) -> ToolResult {
    tracing::debug!("tool: cancel_job {}", args.job_id);
    let outcome = state
        .video_jobs
        .lock()
        .expect("job registry poisoned")
        .request_cancel(args.job_id);
    match outcome {
        None => err_code(
            "JobNotFound",
            format!(
                "job {} unknown or evicted (terminal jobs are retained 10 minutes)",
                args.job_id
            ),
        ),
        Some(true) => ToolResult::text(
            "cancellation requested — the worker stops at its next check point \
             (between frames for exports)",
        ),
        Some(false) => ToolResult::text("job already finished — nothing to cancel"),
    }
}

pub async fn list_export_presets(_state: &AppState, _args: ListExportPresetsArgs) -> ToolResult {
    tracing::debug!("tool: list_export_presets");
    let mut out = Vec::new();
    for p in export_presets::built_in_presets() {
        let mut v = serde_json::to_value(&p).unwrap_or_default();
        v["built_in"] = json!(true);
        out.push(v);
    }
    let customs = export_presets::load_custom_presets().unwrap_or_default();
    for p in customs {
        let mut v = serde_json::to_value(&p).unwrap_or_default();
        v["built_in"] = json!(false);
        out.push(v);
    }
    ToolResult::text(format!("{} export preset(s)", out.len())).with_data(json!({ "presets": out }))
}

pub async fn save_export_preset(_state: &AppState, args: SaveExportPresetArgs) -> ToolResult {
    tracing::debug!("tool: save_export_preset {}", args.name);
    let mut preset: export_presets::ExportPreset = match serde_json::from_value(args.preset) {
        Ok(p) => p,
        Err(e) => {
            return ToolResult::error(format!(
                "invalid preset object: {e} — see list_export_presets output for the serde shape"
            ))
        }
    };
    preset.name = args.name.clone();
    if export_presets::built_in_presets()
        .iter()
        .any(|b| b.name == preset.name)
    {
        return err_code(
            "NotSupportedV1",
            format!(
                "{:?} is a built-in preset (read-only) — choose another name",
                preset.name
            ),
        );
    }
    if let Err(e) = export_presets::validate(&preset) {
        return ToolResult::error(format!("preset failed validation: {e}"));
    }
    let mut customs = match export_presets::load_custom_presets() {
        Ok(c) => c,
        Err(e) => return ToolResult::error(format!("could not read custom presets: {e}")),
    };
    let replaced = customs.iter().any(|p| p.name == preset.name);
    customs.retain(|p| p.name != preset.name);
    customs.push(preset);
    if let Err(e) = export_presets::save_custom_presets(&customs) {
        return ToolResult::error(format!("could not persist custom presets: {e}"));
    }
    ToolResult::text(format!(
        "{} custom preset {:?}",
        if replaced { "updated" } else { "saved" },
        args.name
    ))
}

pub async fn delete_export_preset(_state: &AppState, args: DeleteExportPresetArgs) -> ToolResult {
    tracing::debug!("tool: delete_export_preset {}", args.name);
    if export_presets::built_in_presets()
        .iter()
        .any(|b| b.name == args.name)
    {
        return err_code(
            "NotSupportedV1",
            format!(
                "{:?} is a built-in preset (read-only) — it cannot be deleted",
                args.name
            ),
        );
    }
    let mut customs = match export_presets::load_custom_presets() {
        Ok(c) => c,
        Err(e) => return ToolResult::error(format!("could not read custom presets: {e}")),
    };
    let before = customs.len();
    customs.retain(|p| p.name != args.name);
    if customs.len() == before {
        return ToolResult::error(format!("no custom preset named {:?}", args.name));
    }
    if let Err(e) = export_presets::save_custom_presets(&customs) {
        return ToolResult::error(format!("could not persist custom presets: {e}"));
    }
    ToolResult::text(format!("deleted custom preset {:?}", args.name))
}

// ═════════════════════════════════════════════════════════════════════════════
// P4+ slice (10-mcp-tools.md): captions (§3.8), tts (§3.9), grade (§3.10),
// node graph (§3.11), audio (§3.12), title templates (05 §4b). Every mutating
// handler routes through a committed core op / command (design rule 1): a pure
// `ops`/`graph_ops` fn where one exists, otherwise the exact
// `CaptionCmd`/`AudioCmd`/`TtsCmd`/`GraphCmd`/`TimelineCmd` variant it maps to
// (01 §10), executed via `history.execute_discrete` (design rule 4). Lock order
// is document before history (design rule 7).
// ═════════════════════════════════════════════════════════════════════════════

/// Wrap `cmds` so that `target_seq` is the active sequence while they apply,
/// restoring the prior active sequence afterward — needed because a few core
/// `apply` paths (caption-track *creation* via `BulkInsertCues.created_track`,
/// and every master-bus edit) resolve against `TimelineProject::active_sequence`
/// (01 §10). The whole thing is one undo step and leaves the active sequence
/// unchanged. Degrades to a plain batch/single when `target_seq` is already
/// active.
fn with_active_seq(p: &TimelineProject, target_seq: SequenceId, cmds: Vec<TimelineCmd>) -> Command {
    let prev = p.active_sequence;
    if prev == Some(target_seq) || cmds.is_empty() {
        return batch_or_single(cmds);
    }
    let mut wrapped = Vec::with_capacity(cmds.len() + 2);
    wrapped.push(TimelineCmd::SetActiveSequence {
        old: prev,
        new: Some(target_seq),
    });
    wrapped.extend(cmds);
    wrapped.push(TimelineCmd::SetActiveSequence {
        old: Some(target_seq),
        new: prev,
    });
    Command::Batch(wrapped.into_iter().map(Command::Timeline).collect())
}

fn batch_or_single(cmds: Vec<TimelineCmd>) -> Command {
    if cmds.len() == 1 {
        Command::Timeline(cmds.into_iter().next().unwrap())
    } else {
        Command::Batch(cmds.into_iter().map(Command::Timeline).collect())
    }
}

/// Which `(SequenceId, &CaptionTrack)` owns a caption track id.
fn find_caption_track(p: &TimelineProject, track: TrackId) -> Option<(SequenceId, &CaptionTrack)> {
    for (sid, s) in &p.sequences {
        if let Some(t) = s.caption_tracks.iter().find(|t| t.id == track) {
            return Some((*sid, t));
        }
    }
    None
}

/// Which `(SequenceId, TrackId, &CaptionCue)` owns a cue id.
fn find_cue(p: &TimelineProject, cue: CueId) -> Option<(SequenceId, TrackId, &CaptionCue)> {
    for (sid, s) in &p.sequences {
        for ct in &s.caption_tracks {
            if let Some(c) = ct.cues.iter().find(|c| c.id == cue) {
                return Some((*sid, ct.id, c));
            }
        }
    }
    None
}

fn tick_from_seconds_f64(secs: f64) -> Tick {
    Tick((secs * TICKS_PER_SECOND as f64).round() as i64)
}

fn provider_error_code(e: &captions::ProviderError) -> &'static str {
    use captions::ProviderError::*;
    match e {
        Unauthorized => "ProviderAuthError",
        Unavailable => "ProviderAuthError",
        RateLimited => "RateLimited",
        Timeout => "Timeout",
        Cancelled => "Cancelled",
        _ => "ProviderError",
    }
}

// ─── Captions (10 §3.8) ─────────────────────────────────────────────────────

/// Hosted transcription config from environment (D-04). `None` when unset.
fn hosted_transcription_from_env() -> Option<captions::HostedTranscriptionConfig> {
    let base_url = std::env::var("PHOTONIC_TRANSCRIBE_URL").ok()?;
    let auth = std::env::var("PHOTONIC_TRANSCRIBE_TOKEN")
        .ok()
        .map(|t| ("Authorization".to_string(), format!("Bearer {t}")));
    let path = std::env::var("PHOTONIC_TRANSCRIBE_PATH")
        .unwrap_or_else(|_| "/v1/audio/transcriptions".to_string());
    Some(captions::HostedTranscriptionConfig {
        base_url,
        auth_header: auth,
        shape: captions::TranscriptionEndpointShape::OpenAiCompatible { path },
        extra_timeout: Duration::from_secs(0),
    })
}

enum TranscribeChoice {
    Mock(String),
    Hosted(captions::HostedTranscriptionConfig),
}

pub async fn auto_caption(state: &AppState, args: AutoCaptionArgs) -> ToolResult {
    tracing::debug!("tool: auto_caption");
    let provider = args
        .provider
        .clone()
        .unwrap_or_else(|| "hosted".to_string());

    // Resolve target sequence, the absolute placement range (for the mock
    // fixture), the clip's source span + placement offset (for hosted
    // extraction), and the backing audio file.
    let (seq_id, span, source_range, place_offset, audio_path) = {
        let doc = state.document.lock().await;
        let Some(p) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        if let Some(clip_id) = args.clip_id {
            let Some((sid, tid)) = locate_clip(p, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            let clip = find_clip(p, sid, tid, clip_id).unwrap();
            let audio = match &clip.source {
                ClipSource::Asset { asset } | ClipSource::Vector { asset } => {
                    p.media.assets.get(asset).and_then(|a| match &a.source {
                        photonic_core::timeline::AssetSource::File { path, .. } => {
                            Some(path.clone())
                        }
                        _ => None,
                    })
                }
                _ => None,
            };
            (
                sid,
                (clip.start, clip.end()),
                Some((clip.source_in, clip.source_in + clip.duration)),
                clip.start,
                audio,
            )
        } else if let Some(sid) = args.sequence_id {
            let Some(s) = p.sequences.get(&sid) else {
                return ToolResult::error(format!("sequence {sid} not found"));
            };
            let end = s
                .video_tracks
                .iter()
                .chain(s.audio_tracks.iter())
                .flat_map(|t| t.clips.iter())
                .map(|c| c.end())
                .max()
                .unwrap_or(Tick(0));
            (sid, (Tick(0), end), None, Tick(0), None)
        } else {
            return ToolResult::error("supply one of sequence_id / clip_id");
        }
    };
    if span.1 <= span.0 {
        return err_code(
            "TickOutOfRange",
            "target range is empty (no content to caption)",
        );
    }

    // Validate provider choice synchronously for a clean start-time error.
    let choice = match provider.as_str() {
        "mock" => {
            let Some(text) = args.mock_transcript.clone() else {
                return err_code(
                    "InvalidRequest",
                    "provider=\"mock\" requires mock_transcript (the deterministic offline transcript)",
                );
            };
            TranscribeChoice::Mock(text)
        }
        "hosted" => {
            let Some(cfg) = hosted_transcription_from_env() else {
                return err_code(
                    "ProviderAuthError",
                    "no hosted transcription provider configured — set PHOTONIC_TRANSCRIBE_URL (+ PHOTONIC_TRANSCRIBE_TOKEN), or use provider=\"mock\" with mock_transcript",
                );
            };
            if source_range.is_none() || audio_path.is_none() {
                return err_code(
                    "InvalidRequest",
                    "hosted transcription needs a file-backed clip audio source — pass clip_id of an imported video/audio asset",
                );
            }
            TranscribeChoice::Hosted(cfg)
        }
        other => {
            return err_code(
                "InvalidRequest",
                format!("unknown provider {other:?} — use \"hosted\" or \"mock\""),
            )
        }
    };

    // Resolve or create the destination caption track.
    let (track_id, created_track): (TrackId, Option<Box<CaptionTrack>>) = {
        let doc = state.document.lock().await;
        let p = doc.timeline.as_ref().unwrap();
        match args.track_id {
            Some(tid) if find_caption_track(p, tid).is_some() => (tid, None),
            Some(_) => return ToolResult::error("track_id is not a caption track"),
            None => {
                let ct = CaptionTrack::new(args.name.clone().unwrap_or_else(|| "Captions".into()));
                (ct.id, Some(Box::new(ct)))
            }
        }
    };

    let (job_id, cancel) = match state.video_jobs.lock().expect("job registry poisoned").start("auto_caption") {
        Ok(job) => job,
        Err(error) => return ToolResult::error_with_code("JobCapacityExceeded", error.to_string()).with_data(json!({"retryable":true,"max_active_jobs":crate::handlers::video_jobs::MAX_ACTIVE_JOBS})),
    };
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    let document = std::sync::Arc::clone(&state.document);
    let history = std::sync::Arc::clone(&state.history);
    let language_hint = args.language_hint.clone();

    std::thread::spawn(move || {
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Running {
                progress: 0.1,
                message: "transcribing".into(),
            },
        );
        let cancel_tok = captions::CancelToken::new();
        if cancel.load(Ordering::Relaxed) {
            set_job_status(&jobs, job_id, JobStatus::Cancelled);
            return;
        }
        let (tx, _rx) = crossbeam_channel::unbounded();
        let (words_result, hosted) = match choice {
            TranscribeChoice::Mock(text) => {
                let prov = captions::MockTranscriptionProvider::fixture(&text, span.0, span.1);
                use captions::TranscriptionProvider;
                (
                    prov.transcribe(
                        captions::TranscriptionRequest {
                            audio_path: std::path::PathBuf::from("mock.wav"),
                            language_hint,
                            model: None,
                        },
                        tx,
                        cancel_tok,
                    ),
                    false,
                )
            }
            TranscribeChoice::Hosted(cfg) => {
                let tools = match ffmpeg_locate::locate() {
                    Ok(t) => t,
                    Err(e) => {
                        set_job_status(
                            &jobs,
                            job_id,
                            JobStatus::Failed {
                                error_code: "FfmpegUnavailable".into(),
                                message: format!("ffmpeg not found ({e})"),
                            },
                        );
                        return;
                    }
                };
                let wav = std::env::temp_dir().join(format!("photonic-mcp-autocap-{job_id}.wav"));
                if let Err(e) = captions::extract::extract_audio_48k_mono(
                    &tools,
                    &audio_path.unwrap(),
                    &wav,
                    source_range,
                ) {
                    set_job_status(
                        &jobs,
                        job_id,
                        JobStatus::Failed {
                            error_code: "ExtractFailed".into(),
                            message: e.to_string(),
                        },
                    );
                    return;
                }
                let prov = captions::HostedTranscriptionProvider::new(cfg);
                use captions::TranscriptionProvider;
                let r = prov.transcribe(
                    captions::TranscriptionRequest {
                        audio_path: wav.clone(),
                        language_hint,
                        model: None,
                    },
                    tx,
                    cancel_tok,
                );
                let _ = std::fs::remove_file(&wav);
                (r, true)
            }
        };

        let mut words = match words_result {
            Ok(r) => r.words,
            Err(e) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: provider_error_code(&e).into(),
                        message: e.to_string(),
                    },
                );
                return;
            }
        };
        // Hosted adapters return audio-relative ticks (06 §2.2, §3.4: the
        // offset mapping is the caller's job); shift them to the clip's
        // sequence position. The mock fixture is already absolute.
        if hosted {
            for w in &mut words {
                w.start = w.start + place_offset;
                w.end = w.end + place_offset;
            }
        }
        let cues = captions::group_words_into_cues(&words, &captions::GroupingParams::default());
        let cue_count = cues.len();

        let bulk = TimelineCmd::CaptionEdit(CaptionCmd::BulkInsertCues {
            track: track_id,
            cues,
            replace_range: None,
            replaced: Vec::new(),
            created_track,
        });
        {
            let mut doc = document.blocking_lock();
            let cmd = {
                let p = doc.timeline.as_ref();
                match p {
                    Some(p) => with_active_seq(p, seq_id, vec![bulk]),
                    None => {
                        set_job_status(
                            &jobs,
                            job_id,
                            JobStatus::Failed {
                                error_code: "NoProject".into(),
                                message: "timeline project vanished".into(),
                            },
                        );
                        return;
                    }
                }
            };
            let mut hist = history.blocking_lock();
            hist.execute_discrete(cmd, &mut doc);
            hist.schedule_mcp_checkpoint("auto_caption".to_string());
        }
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Done {
                result: json!({ "track_id": track_id, "cue_count": cue_count }),
            },
        );
    });

    ToolResult::text("auto-caption job started — poll get_job_status")
        .with_data(json!({ "job_id": job_id, "track_id": track_id }))
}

pub async fn add_caption_track(state: &AppState, args: AddCaptionTrackArgs) -> ToolResult {
    tracing::debug!("tool: add_caption_track {}", args.sequence_id);
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    if !p.sequences.contains_key(&args.sequence_id) {
        return ToolResult::error(format!("sequence {} not found", args.sequence_id));
    }
    let track = CaptionTrack::new(args.name.unwrap_or_else(|| "Captions".into()));
    let track_id = track.id;
    let bulk = TimelineCmd::CaptionEdit(CaptionCmd::BulkInsertCues {
        track: track_id,
        cues: Vec::new(),
        replace_range: None,
        replaced: Vec::new(),
        created_track: Some(Box::new(track)),
    });
    let cmd = with_active_seq(p, args.sequence_id, vec![bulk]);
    history.execute_discrete(cmd, &mut doc);
    ToolResult::text("Added caption track").with_data(json!({ "track_id": track_id }))
}

pub async fn remove_caption_track(state: &AppState, args: RemoveCaptionTrackArgs) -> ToolResult {
    tracing::debug!("tool: remove_caption_track {}", args.track_id);
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((_, ct)) = find_caption_track(p, args.track_id) else {
        return ToolResult::error(format!("caption track {} not found", args.track_id));
    };
    let inserted_ids: Vec<CueId> = ct.cues.iter().map(|c| c.id).collect();
    // The committed core has no undoable RemoveCaptionTrack: caption tracks are
    // created/removed only as side effects of bulk cue insertion (06 §3.6).
    // `UndoBulkInsert{remove_track}` removes the track structurally; its inverse
    // is `None`, so this participates in history as a checkpoint but is not a
    // fine-grained undo step (documented in the tool description).
    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::UndoBulkInsert {
        track: args.track_id,
        inserted_ids,
        restored: Vec::new(),
        remove_track: true,
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text("Removed caption track")
}

pub async fn get_caption_track(state: &AppState, args: GetCaptionTrackArgs) -> ToolResult {
    tracing::debug!("tool: get_caption_track {}", args.track_id);
    let doc = state.document.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, ct)) = find_caption_track(p, args.track_id) else {
        return ToolResult::error(format!("caption track {} not found", args.track_id));
    };
    ToolResult::text(format!(
        "caption track \"{}\" — {} cue(s)",
        ct.name,
        ct.cues.len()
    ))
    .with_data(json!({ "sequence_id": seq_id, "track": ct }))
}

/// Build `CaptionWord`s from explicit per-word timing, or distribute `text`
/// proportionally across `[start, end)` (§2.2 fallback math).
fn build_caption_words(
    words: Option<Vec<CaptionWordArg>>,
    text: Option<String>,
    start: Tick,
    end: Tick,
    fr: FrameRate,
) -> Result<Vec<CaptionWord>, ToolResult> {
    if let Some(ws) = words {
        let mut out = Vec::with_capacity(ws.len());
        for w in ws {
            let s = resolve_tick(
                w.start_ticks,
                w.start_tc.as_deref(),
                w.start_seconds,
                Some(fr),
            )?;
            let e = resolve_tick(w.end_ticks, w.end_tc.as_deref(), w.end_seconds, Some(fr))?;
            out.push(CaptionWord::new(w.text, s, e));
        }
        Ok(out)
    } else if let Some(t) = text {
        Ok(
            captions::proportional::distribute_words_proportionally(&t, start, end)
                .into_iter()
                .map(|tw| CaptionWord::new(tw.text, tw.start, tw.end))
                .collect(),
        )
    } else {
        Err(ToolResult::error(
            "supply `words` (per-word timing) or `text`",
        ))
    }
}

pub async fn set_caption_cue(state: &AppState, args: SetCaptionCueArgs) -> ToolResult {
    tracing::debug!("tool: set_caption_cue {}", args.track_id);
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, ct)) = find_caption_track(p, args.track_id) else {
        return ToolResult::error(format!("caption track {} not found", args.track_id));
    };
    let fr = p.sequences.get(&seq_id).unwrap().frame_rate;
    let has_start =
        args.start_ticks.is_some() || args.start_tc.is_some() || args.start_seconds.is_some();
    let has_end = args.end_ticks.is_some() || args.end_tc.is_some() || args.end_seconds.is_some();

    if let Some(cue_id) = args.cue_id {
        // Edit an existing cue: timing + words in one batch (design rule 4).
        let Some(cue) = ct.cues.iter().find(|c| c.id == cue_id) else {
            return ToolResult::error(format!("cue {cue_id} not found on this track"));
        };
        let cue = cue.clone();
        let mut cmds = Vec::new();
        if has_start || has_end {
            let start = if has_start {
                match resolve_tick(
                    args.start_ticks,
                    args.start_tc.as_deref(),
                    args.start_seconds,
                    Some(fr),
                ) {
                    Ok(t) => t,
                    Err(e) => return e,
                }
            } else {
                cue.start
            };
            let end = if has_end {
                match resolve_tick(
                    args.end_ticks,
                    args.end_tc.as_deref(),
                    args.end_seconds,
                    Some(fr),
                ) {
                    Ok(t) => t,
                    Err(e) => return e,
                }
            } else {
                cue.end
            };
            if end <= start {
                return err_code("TickOutOfRange", "cue end must be after start");
            }
            if (start, end) != (cue.start, cue.end) {
                cmds.push(TimelineCmd::CaptionEdit(CaptionCmd::RetimeCue {
                    track: args.track_id,
                    cue: cue_id,
                    old: (cue.start, cue.end),
                    new: (start, end),
                }));
            }
        }
        if args.words.is_some() || args.text.is_some() {
            let new_words = match build_caption_words(args.words, args.text, cue.start, cue.end, fr)
            {
                Ok(w) => w,
                Err(e) => return e,
            };
            cmds.push(TimelineCmd::CaptionEdit(CaptionCmd::SetCueText {
                track: args.track_id,
                cue: cue_id,
                old_words: cue.words.clone(),
                new_words,
            }));
        }
        if cmds.is_empty() {
            return ToolResult::error("nothing to change — supply timing, words, or text");
        }
        history.execute_discrete(batch_or_single(cmds), &mut doc);
        let note = args
            .position_override
            .map(|_| "position_override is only settable on cue creation in v1 — ignored")
            .unwrap_or("");
        ToolResult::text("Updated caption cue").with_data(json!({ "cue_id": cue_id, "note": note }))
    } else {
        // Create a new cue on the (already-existing) track.
        if !has_start || !has_end {
            return ToolResult::error("creating a cue requires both start and end");
        }
        let start = match resolve_tick(
            args.start_ticks,
            args.start_tc.as_deref(),
            args.start_seconds,
            Some(fr),
        ) {
            Ok(t) => t,
            Err(e) => return e,
        };
        let end = match resolve_tick(
            args.end_ticks,
            args.end_tc.as_deref(),
            args.end_seconds,
            Some(fr),
        ) {
            Ok(t) => t,
            Err(e) => return e,
        };
        if end <= start {
            return err_code("TickOutOfRange", "cue end must be after start");
        }
        let words = match build_caption_words(args.words, args.text, start, end, fr) {
            Ok(w) => w,
            Err(e) => return e,
        };
        let mut cue = CaptionCue::new(start, end, words);
        cue.position_override = args.position_override;
        let cue_id = cue.id;
        let cmd = TimelineCmd::CaptionEdit(CaptionCmd::BulkInsertCues {
            track: args.track_id,
            cues: vec![cue],
            replace_range: None,
            replaced: Vec::new(),
            created_track: None,
        });
        history.execute_discrete(Command::Timeline(cmd), &mut doc);
        ToolResult::text("Added caption cue").with_data(json!({ "cue_id": cue_id }))
    }
}

pub async fn split_caption_cue(state: &AppState, args: SplitCaptionCueArgs) -> ToolResult {
    tracing::debug!("tool: split_caption_cue {}", args.cue_id);
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, track_id, cue)) = find_cue(p, args.cue_id) else {
        return ToolResult::error(format!("cue {} not found", args.cue_id));
    };
    let fr = p.sequences.get(&seq_id).unwrap().frame_rate;
    let at = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(fr),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    // Split before the first word that starts at/after `at`.
    let idx = cue.words.iter().take_while(|w| w.start < at).count();
    if idx == 0 || idx >= cue.words.len() {
        return err_code(
            "TickOutOfRange",
            "split point must fall strictly between two words of the cue",
        );
    }
    let new_cue_id = CueId::new();
    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::SplitCue {
        track: track_id,
        cue: args.cue_id,
        at_word_index: idx,
        new_cue_id,
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text("Split caption cue").with_data(json!({ "new_cue_id": new_cue_id }))
}

pub async fn merge_caption_cues(state: &AppState, args: MergeCaptionCuesArgs) -> ToolResult {
    tracing::debug!(
        "tool: merge_caption_cues {} + {}",
        args.cue_id_a,
        args.cue_id_b
    );
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((_, track_a, cue_a)) = find_cue(p, args.cue_id_a) else {
        return ToolResult::error(format!("cue {} not found", args.cue_id_a));
    };
    let cue_a = cue_a.clone();
    let Some((_, track_b, cue_b)) = find_cue(p, args.cue_id_b) else {
        return ToolResult::error(format!("cue {} not found", args.cue_id_b));
    };
    if track_a != track_b {
        return ToolResult::error("merge requires both cues on the same caption track");
    }
    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::MergeCues {
        track: track_a,
        a: args.cue_id_a,
        b: args.cue_id_b,
        old_a: Box::new(cue_a),
        old_b: Box::new(cue_b.clone()),
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text("Merged caption cues")
}

pub async fn set_caption_word(state: &AppState, args: SetCaptionWordArgs) -> ToolResult {
    tracing::debug!(
        "tool: set_caption_word {}[{}]",
        args.cue_id,
        args.word_index
    );
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, track_id, cue)) = find_cue(p, args.cue_id) else {
        return ToolResult::error(format!("cue {} not found", args.cue_id));
    };
    let fr = p.sequences.get(&seq_id).unwrap().frame_rate;
    if args.word_index >= cue.words.len() {
        return ToolResult::error(format!("word index {} out of range", args.word_index));
    }
    let old_words = cue.words.clone();
    let mut new_words = old_words.clone();
    {
        let w = &mut new_words[args.word_index];
        if let Some(t) = args.text {
            w.text = t;
        }
        let has_start =
            args.start_ticks.is_some() || args.start_tc.is_some() || args.start_seconds.is_some();
        let has_end =
            args.end_ticks.is_some() || args.end_tc.is_some() || args.end_seconds.is_some();
        if has_start {
            match resolve_tick(
                args.start_ticks,
                args.start_tc.as_deref(),
                args.start_seconds,
                Some(fr),
            ) {
                Ok(t) => w.start = t,
                Err(e) => return e,
            }
        }
        if has_end {
            match resolve_tick(
                args.end_ticks,
                args.end_tc.as_deref(),
                args.end_seconds,
                Some(fr),
            ) {
                Ok(t) => w.end = t,
                Err(e) => return e,
            }
        }
    }
    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::SetCueText {
        track: track_id,
        cue: args.cue_id,
        old_words,
        new_words,
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text("Updated caption word")
}

fn merge_caption_style(
    base: &CaptionStyle,
    arg: &CaptionStyleArg,
) -> Result<CaptionStyle, ToolResult> {
    let mut s = base.clone();
    if let Some(f) = &arg.font_family {
        s.font_family = f.clone();
    }
    if let Some(v) = arg.font_size {
        s.font_size = v;
    }
    if let Some(v) = arg.weight {
        s.weight = v;
    }
    if let Some(hex) = &arg.fill {
        s.fill = Color::from_hex(hex)
            .ok_or_else(|| ToolResult::error(format!("invalid fill color {hex:?}")))?;
    }
    if arg.clear_stroke && arg.stroke.is_some() {
        return Err(ToolResult::error(
            "clear_stroke and stroke cannot both be supplied",
        ));
    }
    if arg.clear_background && arg.background.is_some() {
        return Err(ToolResult::error(
            "clear_background and background cannot both be supplied",
        ));
    }
    if arg.clear_stroke {
        s.stroke = None;
    }
    if arg.clear_background {
        s.background = None;
    }
    if let Some(stroke) = &arg.stroke {
        if !stroke.width.is_finite() || !(0.0..=8.0).contains(&stroke.width) {
            return Err(ToolResult::error(
                "outline width must be finite in 0..=8 pixels",
            ));
        }
        let color = Color::from_hex(&stroke.color)
            .ok_or_else(|| ToolResult::error("invalid outline color"))?;
        s.stroke = Some((color, stroke.width));
    }
    if let Some(background) = &arg.background {
        if !background.padding.is_finite()
            || !(0.0..=128.0).contains(&background.padding)
            || !background.corner_radius.is_finite()
            || !(0.0..=128.0).contains(&background.corner_radius)
        {
            return Err(ToolResult::error(
                "background padding and corner_radius must be finite in 0..=128 pixels",
            ));
        }
        let color = Color::from_hex(&background.color)
            .ok_or_else(|| ToolResult::error("invalid background color"))?;
        s.background = Some(photonic_core::timeline::CaptionBackground {
            color,
            padding: background.padding,
            corner_radius: background.corner_radius,
        });
    }
    if let Some(direction) = arg.direction {
        s.direction = direction;
    }
    if let Some(animation) = arg.animation {
        s.animation = animation;
    }
    if [
        arg.clear_highlight,
        arg.word_pop.is_some(),
        arg.underline.is_some(),
        arg.fill_sweep.is_some(),
    ]
    .into_iter()
    .filter(|v| *v)
    .count()
        > 1
    {
        return Err(ToolResult::error(
            "clear_highlight, word_pop, underline and fill_sweep are mutually exclusive",
        ));
    }
    if arg.clear_highlight {
        s.highlight = None;
    }
    if let Some(underline) = &arg.underline {
        let active_color = Color::from_hex(&underline.active_color)
            .ok_or_else(|| ToolResult::error("invalid underline active color"))?;
        s.highlight = Some(photonic_core::timeline::KaraokeStyle {
            mode: photonic_core::timeline::KaraokeMode::Underline,
            active_color,
            inactive_color: s.fill,
        });
    }
    if let Some(colors) = &arg.word_pop {
        let active_color = Color::from_hex(&colors.active_color)
            .ok_or_else(|| ToolResult::error("invalid active word-pop color"))?;
        let inactive_color = Color::from_hex(&colors.inactive_color)
            .ok_or_else(|| ToolResult::error("invalid inactive word-pop color"))?;
        s.highlight = Some(photonic_core::timeline::KaraokeStyle {
            mode: photonic_core::timeline::KaraokeMode::WordPop,
            active_color,
            inactive_color,
        });
    }
    if let Some(colors) = &arg.fill_sweep {
        let active_color = Color::from_hex(&colors.active_color)
            .ok_or_else(|| ToolResult::error("invalid active fill-sweep color"))?;
        let inactive_color = Color::from_hex(&colors.inactive_color)
            .ok_or_else(|| ToolResult::error("invalid inactive fill-sweep color"))?;
        s.highlight = Some(photonic_core::timeline::KaraokeStyle {
            mode: photonic_core::timeline::KaraokeMode::FillSweep,
            active_color,
            inactive_color,
        });
    }
    if let Some(pos) = arg.position {
        s.position = pos;
    }
    if let Some(v) = arg.max_width {
        s.max_width = v;
    }
    Ok(s)
}

pub async fn set_caption_style(state: &AppState, args: SetCaptionStyleArgs) -> ToolResult {
    if args.word_index.is_some() && args.style.as_ref().is_some_and(|s| s.direction.is_some()) {
        return ToolResult::error("paragraph direction must be edited at track or cue scope");
    }

    tracing::debug!("tool: set_caption_style");
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    // Resolve the owning track from track_id or the cue.
    let track_id = if let Some(t) = args.track_id {
        t
    } else if let Some(cue) = args.cue_id {
        match find_cue(p, cue) {
            Some((_, t, _)) => t,
            None => return ToolResult::error(format!("cue {cue} not found")),
        }
    } else {
        return ToolResult::error("supply track_id (track scope) or cue_id (cue/word scope)");
    };
    let Some((_, ct)) = find_caption_track(p, track_id) else {
        return ToolResult::error(format!("caption track {track_id} not found"));
    };

    let (target, old, base): (StyleTarget, Option<CaptionStyle>, CaptionStyle) =
        match (args.cue_id, args.word_index) {
            (Some(cue_id), Some(wi)) => {
                let Some(c) = ct.cues.iter().find(|c| c.id == cue_id) else {
                    return ToolResult::error(format!("cue {cue_id} not found on this track"));
                };
                let Some(w) = c.words.get(wi) else {
                    return ToolResult::error(format!("word index {wi} out of range"));
                };
                let base = w
                    .style_override
                    .clone()
                    .or_else(|| c.style_override.clone())
                    .unwrap_or_else(|| ct.style.clone());
                (
                    StyleTarget::Word(cue_id, wi),
                    w.style_override.clone(),
                    base,
                )
            }
            (Some(cue_id), None) => {
                let Some(c) = ct.cues.iter().find(|c| c.id == cue_id) else {
                    return ToolResult::error(format!("cue {cue_id} not found on this track"));
                };
                let base = c.style_override.clone().unwrap_or_else(|| ct.style.clone());
                (StyleTarget::Cue(cue_id), c.style_override.clone(), base)
            }
            (None, _) => (StyleTarget::Track, Some(ct.style.clone()), ct.style.clone()),
        };

    let new: Option<CaptionStyle> = if args.clear && !matches!(target, StyleTarget::Track) {
        None
    } else {
        let arg = args.style.unwrap_or_default();
        match merge_caption_style(&base, &arg) {
            Ok(s) => Some(s),
            Err(e) => return e,
        }
    };

    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::SetStyle {
        track: track_id,
        target,
        old: old.map(Box::new),
        new: new.map(Box::new),
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text("Updated caption style")
}

fn caption_format_from(path: &str, explicit: Option<&str>) -> Option<String> {
    if let Some(f) = explicit {
        return Some(f.to_ascii_lowercase());
    }
    std::path::Path::new(path)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
}

pub async fn import_captions(state: &AppState, args: ImportCaptionsArgs) -> ToolResult {
    tracing::debug!("tool: import_captions {}", args.track_id);
    let cap_path =
        match crate::path_guard::check_path(state, &args.path, photonic_core::PathAccess::Read) {
            Ok(p) => p,
            Err(e) => return e,
        };
    let content = match std::fs::read_to_string(&cap_path) {
        Ok(c) => c,
        Err(e) => return ToolResult::error(format!("could not read {}: {e}", args.path)),
    };
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((_, ct)) = find_caption_track(p, args.track_id) else {
        return ToolResult::error(format!("caption track {} not found", args.track_id));
    };
    let track_name = ct.name.clone();
    let fmt = caption_format_from(&args.path, args.format.as_deref());
    let (cues, notes) = match fmt.as_deref() {
        Some("srt") => match captions::interchange::srt::parse_srt(&content) {
            Ok((c, s)) => (c, s.notes),
            Err(e) => return ToolResult::error(format!("SRT parse error: {e}")),
        },
        Some("vtt") => match captions::interchange::vtt::parse_vtt(&content) {
            Ok((c, s)) => (c, s.notes),
            Err(e) => return ToolResult::error(format!("VTT parse error: {e}")),
        },
        Some("ass") => match captions::interchange::ass::parse_ass(&content, &track_name) {
            Ok(r) => (r.track.cues, r.summary.notes),
            Err(e) => return ToolResult::error(format!("ASS parse error: {e}")),
        },
        other => {
            return ToolResult::error(format!(
                "unknown/unsupported caption format {other:?} — use srt | vtt | ass"
            ))
        }
    };
    let count = cues.len();
    let cmd = TimelineCmd::CaptionEdit(CaptionCmd::BulkInsertCues {
        track: args.track_id,
        cues,
        replace_range: None,
        replaced: Vec::new(),
        created_track: None,
    });
    history.execute_discrete(Command::Timeline(cmd), &mut doc);
    ToolResult::text(format!("Imported {count} caption cue(s)"))
        .with_data(json!({ "cues_imported": count, "notes": notes }))
}

pub async fn export_captions(state: &AppState, args: ExportCaptionsArgs) -> ToolResult {
    tracing::debug!("tool: export_captions {}", args.track_id);
    let doc = state.document.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((_, ct)) = find_caption_track(p, args.track_id) else {
        return ToolResult::error(format!("caption track {} not found", args.track_id));
    };
    let fmt = caption_format_from(&args.path, args.format.as_deref());
    let (text, notes) = match fmt.as_deref() {
        Some("srt") => (
            captions::interchange::srt::write_srt(&ct.cues),
            captions::interchange::direction_export_notes(ct),
        ),
        Some("vtt") => (
            captions::interchange::vtt::write_vtt(&ct.cues, true),
            captions::interchange::direction_export_notes(ct),
        ),
        Some("ass") => {
            let (t, summary) = captions::interchange::ass::write_ass(ct);
            (t, summary.notes)
        }
        other => {
            return ToolResult::error(format!(
                "unknown/unsupported caption format {other:?} — use srt | vtt | ass"
            ))
        }
    };
    let out_path =
        match crate::path_guard::check_path(state, &args.path, photonic_core::PathAccess::Write) {
            Ok(p) => p,
            Err(e) => return e,
        };
    if let Err(e) = std::fs::write(&out_path, text) {
        return ToolResult::error(format!("could not write {}: {e}", out_path.display()));
    }
    ToolResult::text(format!(
        "Exported {} cue(s) to {}",
        ct.cues.len(),
        out_path.display()
    ))
    .with_data(json!({ "path": out_path, "notes": notes }))
}

// ─── TTS (10 §3.9) ───────────────────────────────────────────────────────────

fn hosted_tts_from_env() -> Option<captions::HostedTtsConfig> {
    let base_url = std::env::var("PHOTONIC_TTS_URL").ok()?;
    let auth = std::env::var("PHOTONIC_TTS_TOKEN")
        .ok()
        .map(|t| ("Authorization".to_string(), format!("Bearer {t}")));
    let path =
        std::env::var("PHOTONIC_TTS_PATH").unwrap_or_else(|_| "/v1/audio/speech".to_string());
    let voices_path =
        std::env::var("PHOTONIC_TTS_VOICES_PATH").unwrap_or_else(|_| "/v1/voices".to_string());
    Some(captions::HostedTtsConfig {
        base_url,
        auth_header: auth,
        synthesize_shape: captions::TtsEndpointShape::OpenAiCompatible { path },
        voices_path,
        extra_timeout: Duration::from_secs(0),
    })
}

enum TtsChoice {
    Mock,
    Hosted(captions::HostedTtsConfig),
}

pub async fn generate_voiceover(state: &AppState, args: GenerateVoiceoverArgs) -> ToolResult {
    tracing::debug!("tool: generate_voiceover");
    if args.text.trim().is_empty() {
        return ToolResult::error("text must not be empty");
    }
    let provider = args
        .provider
        .clone()
        .unwrap_or_else(|| "hosted".to_string());
    let (seq_id, fr) = {
        let doc = state.document.lock().await;
        let Some(p) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some(seq_id) = locate_track(p, args.track_id) else {
            return ToolResult::error(format!("track {} not found", args.track_id));
        };
        (seq_id, p.sequences.get(&seq_id).unwrap().frame_rate)
    };
    let start = match resolve_tick(
        args.start_ticks,
        args.start_tc.as_deref(),
        args.start_seconds,
        Some(fr),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    let choice = match provider.as_str() {
        "mock" => TtsChoice::Mock,
        "hosted" => match hosted_tts_from_env() {
            Some(cfg) => TtsChoice::Hosted(cfg),
            None => {
                return err_code(
                    "ProviderAuthError",
                    "no hosted TTS provider configured — set PHOTONIC_TTS_URL (+ PHOTONIC_TTS_TOKEN), or use provider=\"mock\"",
                )
            }
        },
        other => return err_code("InvalidRequest", format!("unknown provider {other:?}")),
    };
    let voice = args
        .voice
        .clone()
        .unwrap_or_else(|| "mock-voice".to_string());

    let (job_id, cancel) = match state.video_jobs.lock().expect("job registry poisoned").start("generate_voiceover") {
        Ok(job) => job,
        Err(error) => return ToolResult::error_with_code("JobCapacityExceeded", error.to_string()).with_data(json!({"retryable":true,"max_active_jobs":crate::handlers::video_jobs::MAX_ACTIVE_JOBS})),
    };
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    let document = std::sync::Arc::clone(&state.document);
    let history = std::sync::Arc::clone(&state.history);
    let text = args.text.clone();
    let track_id = args.track_id;
    let also_caption = args.also_caption;
    let caption_track_id = args.caption_track_id;

    std::thread::spawn(move || {
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Running {
                progress: 0.2,
                message: "synthesizing".into(),
            },
        );
        if cancel.load(Ordering::Relaxed) {
            set_job_status(&jobs, job_id, JobStatus::Cancelled);
            return;
        }
        let (tx, _rx) = crossbeam_channel::unbounded();
        let req = captions::TtsRequest {
            text: text.clone(),
            voice,
            params: std::collections::HashMap::new(),
        };
        use captions::TtsProvider;
        let result = match choice {
            TtsChoice::Mock => captions::MockTtsProvider::default().synthesize(
                req,
                tx,
                captions::CancelToken::new(),
            ),
            TtsChoice::Hosted(cfg) => captions::HostedTtsProvider::new(cfg).synthesize(
                req,
                tx,
                captions::CancelToken::new(),
            ),
        };
        let result = match result {
            Ok(r) => r,
            Err(e) => {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: provider_error_code(&e).into(),
                        message: e.to_string(),
                    },
                );
                return;
            }
        };
        // Persist the synthesized WAV in the proxy/sidecar cache dir and import
        // it as a file-backed audio asset.
        let duration_secs = captions::wav::read_wav_info(&result.audio)
            .map(|i| i.duration_secs())
            .unwrap_or(0.0);
        let dur_ticks = tick_from_seconds_f64(duration_secs).max(Tick(1));
        let cache_dir = video_proxy::proxy_cache_dir(None);
        let _ = std::fs::create_dir_all(&cache_dir);
        let wav_path = cache_dir.join(format!("tts-{job_id}.wav"));
        if let Err(e) = std::fs::write(&wav_path, &result.audio) {
            set_job_status(
                &jobs,
                job_id,
                JobStatus::Failed {
                    error_code: "WriteFailed".into(),
                    message: format!("could not write voiceover audio: {e}"),
                },
            );
            return;
        }
        let asset = photonic_core::timeline::MediaAsset::from_file(AssetKind::Audio, wav_path);
        let asset_id = asset.id;
        let clip = Clip::new(ClipSource::Asset { asset: asset_id }, start, dur_ticks);
        let clip_id = clip.id;

        // Optional word-level captions from the provider's own alignment.
        let caption_cues: Vec<CaptionCue> = if also_caption {
            match &result.word_timings {
                Some(words) => {
                    let shifted: Vec<captions::TranscribedWord> = words
                        .iter()
                        .map(|w| captions::TranscribedWord {
                            text: w.text.clone(),
                            start: w.start + start,
                            end: w.end + start,
                            confidence: w.confidence,
                        })
                        .collect();
                    captions::group_words_into_cues(&shifted, &captions::GroupingParams::default())
                }
                None => Vec::new(),
            }
        } else {
            Vec::new()
        };

        let mut doc = document.blocking_lock();
        let cmd = {
            let Some(p) = doc.timeline.as_ref() else {
                set_job_status(
                    &jobs,
                    job_id,
                    JobStatus::Failed {
                        error_code: "NoProject".into(),
                        message: "timeline project vanished".into(),
                    },
                );
                return;
            };
            let ins = match ops::insert_clip(p, seq_id, track_id, clip) {
                Ok(c) => c,
                Err(e) => {
                    drop(doc);
                    set_job_status(
                        &jobs,
                        job_id,
                        JobStatus::Failed {
                            error_code: "InsertFailed".into(),
                            message: format!("could not place voiceover clip: {e}"),
                        },
                    );
                    return;
                }
            };
            let mut cmds = vec![ops::add_asset(asset), ins];
            let mut cap_track: Option<TrackId> = None;
            if !caption_cues.is_empty() {
                let (ctrack, created) =
                    match caption_track_id.and_then(|t| find_caption_track(p, t).map(|_| t)) {
                        Some(t) => (t, None),
                        None => {
                            let ct = CaptionTrack::new("Voiceover captions");
                            (ct.id, Some(Box::new(ct)))
                        }
                    };
                cap_track = Some(ctrack);
                cmds.push(TimelineCmd::CaptionEdit(CaptionCmd::BulkInsertCues {
                    track: ctrack,
                    cues: caption_cues.clone(),
                    replace_range: None,
                    replaced: Vec::new(),
                    created_track: created,
                }));
            }
            let _ = cap_track;
            with_active_seq(p, seq_id, cmds)
        };
        let mut hist = history.blocking_lock();
        hist.execute_discrete(cmd, &mut doc);
        hist.schedule_mcp_checkpoint("generate_voiceover".to_string());
        drop(hist);
        drop(doc);
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Done {
                result: json!({
                    "asset_id": asset_id,
                    "clip_id": clip_id,
                    "duration_ticks": dur_ticks.0,
                    "captioned": !caption_cues.is_empty(),
                }),
            },
        );
    });

    ToolResult::text("voiceover job started — poll get_job_status")
        .with_data(json!({ "job_id": job_id }))
}

// ─── Grade (10 §3.10) ────────────────────────────────────────────────────────

pub async fn set_grade(state: &AppState, args: SetGradeArgs) -> ToolResult {
    tracing::debug!("tool: set_grade {}", args.clip_id);
    let new_grade: Option<Grade> = match args.grade {
        None | Some(serde_json::Value::Null) => None,
        Some(v) => match serde_json::from_value::<Grade>(v) {
            Ok(g) => Some(g),
            Err(e) => {
                return ToolResult::error(format!(
                "invalid grade object: {e} — see get_clip output / 07 §1 for the Grade serde shape"
            ))
            }
        },
    };
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, track_id)) = locate_clip(p, args.clip_id) else {
        return ToolResult::error(format!("clip {} not found", args.clip_id));
    };
    match ops::set_grade(p, seq_id, track_id, args.clip_id, new_grade) {
        Ok(cmd) => {
            history.execute_discrete(Command::Timeline(cmd), &mut doc);
            ToolResult::text("Updated grade")
        }
        Err(e) => map_edit_error(e),
    }
}

pub async fn group_grade(state: &AppState, args: GroupGradeArgs) -> ToolResult {
    let owner = match args.stage {
        GroupGradeStageArg::Pre => VfxOwner::GroupPre(args.group_id),
        GroupGradeStageArg::Post => VfxOwner::GroupPost(args.group_id),
    };
    if matches!(args.op, GroupGradeOpArg::Get) {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        return match ops::scope_grade(project, owner) {
            Ok(grade) => ToolResult::text("Group grade").with_data(
                json!({ "group_id": args.group_id, "stage": args.stage, "grade": grade }),
            ),
            Err(error) => map_edit_error(error),
        };
    }
    let Some(value) = args.grade else {
        return ToolResult::error("op=set requires grade (null clears it)");
    };
    let grade = if value.is_null() {
        None
    } else {
        match serde_json::from_value::<Grade>(value) {
            Ok(grade) => Some(grade),
            Err(error) => return ToolResult::error(format!("invalid grade object: {error}")),
        }
    };
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    match ops::set_grade_scoped(project, owner, grade) {
        Ok(command) => {
            history.execute_discrete(Command::Timeline(command), &mut doc);
            ToolResult::text("Updated group grade")
        }
        Err(error) => map_edit_error(error),
    }
}

pub async fn grade_version(state: &AppState, args: GradeVersionArgs) -> ToolResult {
    use photonic_core::timeline::GradeInspectionStage as S;
    if let S::SharedLook { id } = args.stage {
        return shared_look_grade_version(state, args, id).await;
    }
    if args.stage != S::Clip {
        return ToolResult::error(
            "named versions support clip or its exact linked shared look stage",
        );
    }

    let mut doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((sequence, track)) = locate_clip(project, args.clip_id) else {
        return ToolResult::error(format!("clip {} not found", args.clip_id));
    };
    if matches!(args.op, GradeVersionOp::List) {
        let Some(clip) = find_clip(project, sequence, track, args.clip_id) else {
            return ToolResult::error("clip disappeared during lookup");
        };
        return ToolResult::text("Grade versions").with_data(json!({
            "clip_id": args.clip_id,
            "active_version": clip.active_grade_version,
            "versions": clip.grade_versions,
        }));
    }
    let command = match args.op {
        GradeVersionOp::List => unreachable!(),
        GradeVersionOp::Add => match args.name.as_deref() {
            Some(name) => ops::add_grade_version(project, sequence, track, args.clip_id, name),
            None => return ToolResult::error("name is required for add"),
        },
        GradeVersionOp::Activate => match args.version_id {
            Some(id) => ops::activate_grade_version(project, sequence, track, args.clip_id, id),
            None => return ToolResult::error("version_id is required for activate"),
        },
        GradeVersionOp::Rename => match (args.version_id, args.name.as_deref()) {
            (Some(id), Some(name)) => {
                ops::rename_grade_version(project, sequence, track, args.clip_id, id, name)
            }
            _ => return ToolResult::error("version_id and name are required for rename"),
        },
        GradeVersionOp::Remove => match args.version_id {
            Some(id) => ops::remove_grade_version(project, sequence, track, args.clip_id, id),
            None => return ToolResult::error("version_id is required for remove"),
        },
    };
    let command = match command {
        Ok(command) => command,
        Err(error) => return map_edit_error(error),
    };
    let mut history = state.history.lock().await;
    history.execute_discrete(Command::Timeline(command), &mut doc);
    let clip = doc
        .timeline
        .as_ref()
        .and_then(|project| find_clip(project, sequence, track, args.clip_id));
    ToolResult::text("Updated grade version").with_data(json!({
        "clip_id": args.clip_id,
        "active_version": clip.and_then(|c| c.active_grade_version),
        "versions": clip.map(|c| &c.grade_versions),
    }))
}

async fn shared_look_grade_version(
    state: &AppState,
    args: GradeVersionArgs,
    id: photonic_core::timeline::SharedLookId,
) -> ToolResult {
    use photonic_core::timeline::shared_look_versions::{
        edit_shared_look_version, SharedLookVersionEdit as E,
    };
    let mut doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((sequence, track)) = locate_clip(project, args.clip_id) else {
        return ToolResult::error("selected clip not found");
    };
    let Some(clip) = find_clip(project, sequence, track, args.clip_id) else {
        return ToolResult::error("selected clip not found");
    };
    if clip.look != Some(photonic_core::timeline::ClipLook::Shared(id)) {
        return ToolResult::error("selected clip is not linked to the addressed shared look");
    }
    let Some(look) = project.shared_looks.get(&id) else {
        return ToolResult::error("shared look is missing");
    };
    let affected = project
        .sequences
        .values()
        .flat_map(|s| s.tracks())
        .flat_map(|t| &t.clips)
        .filter(|c| c.look == Some(photonic_core::timeline::ClipLook::Shared(id)))
        .count();
    if matches!(args.op, GradeVersionOp::List) {
        return ToolResult::text("Shared look versions").with_data(json!({"clip_id":args.clip_id,"stage":args.stage,"look_id":id,"affected_linked_clips":affected,"active_version":look.active_version,"versions":look.versions}));
    }
    let edit = match args.op {
        GradeVersionOp::List => unreachable!(),
        GradeVersionOp::Add => match args.name {
            Some(name) => E::Add(name),
            None => return ToolResult::error("name is required for add"),
        },
        GradeVersionOp::Activate => match args.version_id {
            Some(id) => E::Activate(id),
            None => return ToolResult::error("version_id is required for activate"),
        },
        GradeVersionOp::Rename => match (args.version_id, args.name) {
            (Some(id), Some(name)) => E::Rename(id, name),
            _ => return ToolResult::error("version_id and name are required for rename"),
        },
        GradeVersionOp::Remove => match args.version_id {
            Some(id) => E::Remove(id),
            None => return ToolResult::error("version_id is required for remove"),
        },
    };
    let command = match edit_shared_look_version(project, id, edit) {
        Ok(cmd) => cmd,
        Err(error) => return map_edit_error(error),
    };
    let mut history = state.history.lock().await;
    history.execute_discrete(Command::Timeline(command), &mut doc);
    let look = &doc.timeline.as_ref().unwrap().shared_looks[&id];
    ToolResult::text("Updated shared look version").with_data(json!({"clip_id":args.clip_id,"stage":args.stage,"look_id":id,"affected_linked_clips":affected,"active_version":look.active_version,"versions":look.versions}))
}

pub async fn shared_look(state: &AppState, args: SharedLookArgs) -> ToolResult {
    let mut doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    if matches!(args.op, SharedLookOp::List) {
        let mut looks: Vec<_> = project.shared_looks.values().collect();
        looks.sort_by(|a, b| a.name.cmp(&b.name).then(a.id.0.cmp(&b.id.0)));
        return ToolResult::text("Shared looks").with_data(json!({ "looks": looks }));
    }
    let command = match args.op {
        SharedLookOp::List => unreachable!(),
        SharedLookOp::Create => {
            let Some(name) = args.name.as_deref() else {
                return ToolResult::error("name is required for create");
            };
            let grade = match args.grade {
                Some(value) => match serde_json::from_value::<Grade>(value) {
                    Ok(grade) => grade,
                    Err(error) => {
                        return ToolResult::error(format!("invalid grade object: {error}"))
                    }
                },
                None => Grade::default(),
            };
            ops::create_shared_look(project, name, grade)
        }
        SharedLookOp::Update => {
            let Some(id) = args.look_id else {
                return ToolResult::error("look_id is required for update");
            };
            let Some(existing) = project.shared_looks.get(&id) else {
                return ToolResult::error(format!("shared look {id} not found"));
            };
            let name = args.name.as_deref().unwrap_or(&existing.name);
            let grade = match args.grade {
                Some(value) => match serde_json::from_value::<Grade>(value) {
                    Ok(grade) => grade,
                    Err(error) => {
                        return ToolResult::error(format!("invalid grade object: {error}"))
                    }
                },
                None => existing.grade.clone(),
            };
            ops::update_shared_look(project, id, name, grade)
        }
        SharedLookOp::Remove => match args.look_id {
            Some(id) => ops::remove_shared_look(project, id),
            None => return ToolResult::error("look_id is required for remove"),
        },
        SharedLookOp::Link => {
            let (Some(id), Some(clip_id)) = (args.look_id, args.clip_id) else {
                return ToolResult::error("look_id and clip_id are required for link");
            };
            let Some((sequence, track)) = locate_clip(project, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            ops::link_shared_look(project, sequence, track, clip_id, id)
        }
        SharedLookOp::UpdateIndependent => {
            if args.look_id.is_some() || args.name.is_some() {
                return ToolResult::error(
                    "update_independent accepts clip_id and grade, not look_id or name",
                );
            }
            let (Some(clip_id), Some(value)) = (args.clip_id, args.grade) else {
                return ToolResult::error("clip_id and grade are required for update_independent");
            };
            let Some((sequence, track)) = locate_clip(project, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            let grade = match serde_json::from_value::<Grade>(value) {
                Ok(grade) => grade,
                Err(error) => return ToolResult::error(format!("invalid grade object: {error}")),
            };
            ops::set_clip_stage_grade(
                project,
                sequence,
                track,
                clip_id,
                photonic_core::timeline::GradeInspectionStage::LocalLook,
                grade,
            )
        }
        SharedLookOp::MakeIndependent => {
            let Some(clip_id) = args.clip_id else {
                return ToolResult::error("clip_id is required for make_independent");
            };
            let Some((sequence, track)) = locate_clip(project, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            ops::make_shared_look_independent(project, sequence, track, clip_id)
        }
    };
    let command = match command {
        Ok(command) => command,
        Err(error) => return map_edit_error(error),
    };
    let mut history = state.history.lock().await;
    history.execute_discrete(Command::Timeline(command), &mut doc);
    ToolResult::text("Updated shared look").with_data(json!({
        "looks": doc.timeline.as_ref().map(|project| &project.shared_looks),
        "clip_id": args.clip_id,
    }))
}

pub async fn list_reference_stills(state: &AppState, args: ListReferenceStillsArgs) -> ToolResult {
    let (sequence_id, color, format_index, entries) = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some(sequence_id) = args.sequence_id.or(project.active_sequence) else {
            return ToolResult::error("no active sequence; provide sequence_id");
        };
        let Some(sequence) = project.sequences.get(&sequence_id) else {
            return ToolResult::error(format!("sequence {sequence_id} not found"));
        };
        let entries: Vec<_> = sequence
            .reference_stills
            .iter()
            .map(|still| {
                (
                    still.clone(),
                    project
                        .media
                        .assets
                        .get(&still.image_asset)
                        .map(|asset| asset.source.clone()),
                )
            })
            .collect();
        (
            sequence_id,
            sequence.color.clone(),
            sequence.active_format,
            entries,
        )
    };
    let project_path = state.document_path.lock().unwrap().clone();
    let rows: Vec<_> = entries
        .into_iter()
        .map(|(still, source)| {
            let (image_status, diagnostic) = match source {
                None => (
                    "asset_missing",
                    Some("reference image asset is missing".to_string()),
                ),
                Some(photonic_core::timeline::AssetSource::File { path, rel_path }) => {
                    let relative = project_path
                        .as_ref()
                        .and_then(|project| project.parent())
                        .and_then(|dir| rel_path.as_ref().map(|rel| dir.join(rel)));
                    let resolved = relative
                        .filter(|candidate| candidate.is_file())
                        .or_else(|| path.is_file().then_some(path));
                    match resolved {
                        None => ("offline", Some("reference image is offline".to_string())),
                        Some(_) if still.image_hash.is_empty() => (
                            "hash_missing",
                            Some("full image hash is missing".to_string()),
                        ),
                        Some(path) => match photonic_video::media::full_content_hash(&path) {
                            Ok(hash) if hash == still.image_hash => ("verified", None),
                            Ok(_) => (
                                "changed",
                                Some("reference image changed since capture".to_string()),
                            ),
                            Err(error) => ("unreadable", Some(error.to_string())),
                        },
                    }
                }
                Some(_) => (
                    "unsupported_source",
                    Some("reference image is not a file".to_string()),
                ),
            };
            let comparable = (color.is_legacy()
                || matches!(
                    color,
                    photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
                ))
                && image_status == "verified"
                && still.color == color
                && still.format_index == format_index;
            json!({
                "reference": still,
                "image_status": image_status,
                "comparable": comparable,
                "diagnostic": diagnostic,
            })
        })
        .collect();
    ToolResult::text("Reference stills").with_data(json!({
        "sequence_id": sequence_id,
        "stills": rows,
    }))
}

pub async fn copy_reference_still(state: &AppState, args: CopyReferenceStillArgs) -> ToolResult {
    let mut doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some(destination) = args.destination_sequence_id.or(project.active_sequence) else {
        return ToolResult::error("provide destination_sequence_id");
    };
    let command = match photonic_core::timeline::reference_gallery::copy_reference_still(
        project,
        args.source_sequence_id,
        destination,
        args.still_id,
        args.name.as_deref(),
    ) {
        Ok(c) => c,
        Err(e) => return map_edit_error(e),
    };
    let id = match &command {
        TimelineCmd::SetReferenceStills { new, .. } => new.last().unwrap().id,
        _ => unreachable!(),
    };
    state
        .history
        .lock()
        .await
        .execute_discrete(Command::Timeline(command), &mut doc);
    ToolResult::text("Copied immutable reference to destination gallery").with_data(json!({"sequence_id":destination,"still_id":id,"source_sequence_id":args.source_sequence_id,"source_still_id":args.still_id}))
}

pub async fn remove_reference_still(
    state: &AppState,
    args: RemoveReferenceStillArgs,
) -> ToolResult {
    let mut doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some(sequence_id) = args.sequence_id.or(project.active_sequence) else {
        return ToolResult::error("no active sequence; provide sequence_id");
    };
    let command = match ops::remove_reference_still(project, sequence_id, args.still_id) {
        Ok(command) => command,
        Err(error) => return map_edit_error(error),
    };
    let mut history = state.history.lock().await;
    history.execute_discrete(Command::Timeline(command), &mut doc);
    ToolResult::text("Removed reference still").with_data(json!({
        "sequence_id": sequence_id,
        "still_id": args.still_id,
    }))
}

async fn render_reference_frame(
    state: &AppState,
    sequence_id: SequenceId,
    format_index: usize,
    time: i64,
    revision: u64,
    document_id: uuid::Uuid,
    expected_encoding: photonic_video::graph::ir::FrameColorEncoding,
) -> Result<
    (
        Vec<u8>,
        Tick,
        Option<photonic_core::timeline::native_balance::NativeBalanceSummary>,
    ),
    ToolResult,
> {
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return Err(err_code(
            "RevisionConflict",
            "document changed before reference rendering",
        ));
    }
    let native_size = {
        let doc = state.document.lock().await;
        doc.timeline
            .as_ref()
            .and_then(|p| p.sequences.get(&sequence_id))
            .filter(|s| {
                matches!(
                    s.color,
                    photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
                )
            })
            .and_then(|s| s.formats.get(format_index))
            .map(|f| (f.width, f.height))
    };
    // Keep display-only capture available above the analysis bound. Never
    // reconstruct scene values from the PNG for older or larger references.
    if expected_encoding == photonic_video::graph::ir::FrameColorEncoding::SrgbDisplay
        && native_size.is_some_and(|(w, h)| {
            u64::from(w) * u64::from(h)
                <= photonic_core::timeline::native_balance::NATIVE_BALANCE_MAX_PIXELS
        })
    {
        let mut frame = render_tap_pixels_mode(
            state,
            sequence_id,
            Tick(time),
            Some(format_index),
            ScopeTapPoint::NativeSceneProgram,
            ScopeReadbackMode::ProgramOutput,
        )
        .await?;
        if frame.revision != revision
            || frame.tap != ScopeTapPoint::NativeSceneProgram
            || frame.encoding != photonic_video::graph::ir::FrameColorEncoding::SceneLinearAcescg
            || native_size != Some((frame.width, frame.height))
        {
            return Err(err_code(
                "ReferenceFrameInvalid",
                "native reference scene frame changed",
            ));
        }
        let scene = std::mem::take(&mut frame.pixels);
        let display = frame.display_pixels.take().ok_or_else(|| {
            err_code(
                "ReferenceFrameInvalid",
                "paired reference display is absent",
            )
        })?;
        let (width, height) = (frame.width, frame.height);
        let (png, balance) = match tokio::task::spawn_blocking(move || -> Result<_, String> {
            let measured =
                photonic_render::scene_measurement::measure_pair(&scene, &display, width, height)
                    .map_err(str::to_string)?;
            let balance =
                photonic_video::native_shot_match::measure_native_balance(&scene, width, height)
                    .ok();
            let image = image::RgbaImage::from_raw(width, height, measured.display_rgba)
                .ok_or("invalid reference dimensions")?;
            let mut png = Vec::new();
            image
                .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
                .map_err(|e| e.to_string())?;
            Ok((png, balance))
        })
        .await
        {
            Ok(Ok(result)) => result,
            Ok(Err(e)) => return Err(err_code("ReferenceFrameInvalid", e)),
            Err(e) => return Err(err_code("ReferenceFrameInvalid", e.to_string())),
        };
        if state.document.lock().await.id != document_id
            || state.history.lock().await.revision() != revision
        {
            return Err(err_code(
                "RevisionConflict",
                "document changed during native reference rendering",
            ));
        }
        return Ok((png, frame.time, balance));
    }

    let rendered = render_frame_at(
        state,
        RenderFrameAtArgs {
            sequence_id,
            at_ticks: Some(time),
            at_tc: None,
            at_seconds: None,
            format_index: Some(format_index),
            quality: RenderQualityArg::Full,
            scale: Some(1.0),
            output_format: Some(RenderOutputFormatArg::Png),
        },
    )
    .await;
    if rendered.is_error == Some(true) {
        return Err(rendered);
    }
    let Some(frame) = rendered.structured_content.as_ref() else {
        return Err(ToolResult::error("full-quality frame has no metadata"));
    };
    if frame["revision"] != json!(revision)
        || frame["format_index"] != json!(format_index)
        || frame["quality"] != "full"
        || frame["processing_quality"] != "full"
        || frame["gpu_downscaled"] != false
        || frame["cached_preview"] != false
        || frame["output_encoding"] != json!(format!("{expected_encoding:?}"))
        || frame["grading_errors"]
            .as_array()
            .is_none_or(|errors| !errors.is_empty())
    {
        return Err(err_code(
            "ReferenceFrameInvalid",
            "full-quality frame is stale, degraded or has grading errors",
        ));
    }
    let Some(time) = frame["tick"].as_i64() else {
        return Err(ToolResult::error("rendered frame has no exact time"));
    };
    let Some(encoded) = rendered.content.iter().find_map(|item| match item {
        crate::protocol::ContentItem::Image { data, .. } => Some(data),
        _ => None,
    }) else {
        return Err(ToolResult::error("rendered frame has no PNG image"));
    };
    let bytes = general_purpose::STANDARD
        .decode(encoded)
        .map_err(|error| ToolResult::error(format!("invalid rendered PNG: {error}")))?;
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return Err(err_code(
            "RevisionConflict",
            "document changed during reference rendering",
        ));
    }
    Ok((bytes, Tick(time), None))
}

pub async fn capture_reference_still(
    state: &AppState,
    args: CaptureReferenceStillArgs,
) -> ToolResult {
    use photonic_core::timeline::{AssetSource, MediaAsset, ReferenceStill};
    let Some(project_path) = state.document_path.lock().unwrap().clone() else {
        return ToolResult::error("save the project before capturing a reference still");
    };
    let (sequence_id, format_index, color, default_name, document_id) = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some(sequence_id) = args.sequence_id.or(project.active_sequence) else {
            return ToolResult::error("no active sequence; provide sequence_id");
        };
        let Some(sequence) = project.sequences.get(&sequence_id) else {
            return ToolResult::error(format!("sequence {sequence_id} not found"));
        };
        if !sequence.color.is_legacy()
            && !matches!(
                sequence.color,
                photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
            )
        {
            return err_code(
                "ColorPipelineUnavailable",
                "managed-color reference capture is unavailable until its output transform is qualified",
            );
        }
        (
            sequence_id,
            sequence.active_format,
            sequence.color.clone(),
            format!("Still {}", sequence.reference_stills.len() + 1),
            doc.id,
        )
    };
    let revision = state.history.lock().await.revision();
    let (bytes, rendered_time, native_balance) = match render_reference_frame(
        state,
        sequence_id,
        format_index,
        args.at_ticks,
        revision,
        document_id,
        if color.is_legacy() {
            photonic_video::graph::ir::FrameColorEncoding::LegacyLinearRec709
        } else {
            photonic_video::graph::ir::FrameColorEncoding::SrgbDisplay
        },
    )
    .await
    {
        Ok(frame) => frame,
        Err(error) => return error,
    };
    let native_balance_available = native_balance.is_some();
    let id = uuid::Uuid::new_v4();
    let relative = std::path::PathBuf::from("reference-stills").join(format!("{id}.png"));
    let path = project_path
        .parent()
        .unwrap_or(std::path::Path::new("."))
        .join(&relative);
    if let Some(parent) = path.parent() {
        if let Err(error) = std::fs::create_dir_all(parent) {
            return ToolResult::error(format!("could not create reference directory: {error}"));
        }
    }
    let temporary = path.with_extension(format!("{}.tmp", uuid::Uuid::new_v4()));
    if let Err(error) =
        std::fs::write(&temporary, &bytes).and_then(|_| std::fs::rename(&temporary, &path))
    {
        let _ = std::fs::remove_file(&temporary);
        return ToolResult::error(format!("could not save reference image: {error}"));
    }
    let result = {
        let mut doc = state.document.lock().await;
        let mut history = state.history.lock().await;
        (|| -> Result<_, String> {
            if doc.id != document_id
                || history.revision() != revision
                || *state.document_path.lock().unwrap() != Some(project_path.clone())
            {
                return Err("project changed during capture".into());
            }
            let project = doc
                .timeline
                .as_ref()
                .ok_or("timeline project disappeared")?;
            let sequence = project
                .sequences
                .get(&sequence_id)
                .ok_or("sequence disappeared")?;
            if sequence.active_format != format_index || sequence.color != color {
                return Err("sequence color or format changed during capture".into());
            }
            let source_clip = if let Some(clip_id) = args.source_clip_id {
                let valid = sequence
                    .video_tracks
                    .iter()
                    .flat_map(|track| &track.clips)
                    .any(|clip| {
                        clip.id == clip_id
                            && clip.start <= rendered_time
                            && rendered_time < clip.end()
                    });
                if !valid {
                    return Err("source_clip_id is not visible at the captured time".into());
                }
                Some(clip_id)
            } else {
                None
            };
            let mut asset = MediaAsset::new(
                AssetKind::Image,
                AssetSource::File {
                    path: path.clone(),
                    rel_path: Some(relative),
                },
            );
            asset.content_hash =
                Some(photonic_video::media::content_hash(&path).map_err(|e| e.to_string())?);
            let image_hash =
                photonic_video::media::full_content_hash(&path).map_err(|e| e.to_string())?;
            let native_balance = native_balance.map(|summary| {
                photonic_core::timeline::native_balance::NativeReferenceBalance {
                    summary,
                    image_hash: image_hash.clone(),
                }
            });
            let still = ReferenceStill {
                copied_from: None,
                id,
                name: args.name.unwrap_or(default_name),
                image_asset: asset.id,
                image_hash,
                source_clip,
                source_time: rendered_time,
                grade_revision: revision,
                color,
                native_balance,
                format_index,
            };
            let mut projected = project.clone();
            projected.media.insert(asset.clone());
            let command = ops::add_reference_still(&projected, sequence_id, still)
                .map_err(|error| error.to_string())?;
            history.execute_discrete(
                Command::Batch(vec![
                    Command::Timeline(TimelineCmd::AddAsset {
                        asset: Box::new(asset),
                    }),
                    Command::Timeline(command),
                ]),
                &mut doc,
            );
            Ok(())
        })()
    };
    if let Err(error) = result {
        let _ = std::fs::remove_file(&path);
        return ToolResult::error(format!("reference capture failed: {error}"));
    }
    ToolResult::text("Captured reference still").with_data(json!({
        "sequence_id": sequence_id,
        "still_id": id,
        "time_ticks": rendered_time.0,
        "revision": revision,
        "native_balance_available": native_balance_available,
    }))
}

/// Display-referred comparison of two same-sized RGBA8 images. RGB is
/// composited over black before measurement so transparent hidden colors do
/// not dominate the result. These are inspection metrics, not a color match.
fn reference_rgb_metrics(reference: &[u8], current: &[u8]) -> Option<Value> {
    if reference.len() != current.len()
        || reference.is_empty()
        || !reference.len().is_multiple_of(4)
    {
        return None;
    }
    let pixels = reference.len() / 4;
    let mut signed = [0.0f64; 3];
    let mut abs = 0.0f64;
    let mut squared = 0.0f64;
    let mut alpha_abs = 0.0f64;
    let mut histogram = [0usize; 256];
    for (r, c) in reference.chunks_exact(4).zip(current.chunks_exact(4)) {
        let ra = f64::from(r[3]) / 255.0;
        let ca = f64::from(c[3]) / 255.0;
        alpha_abs += (ca - ra).abs();
        for channel in 0..3 {
            let delta = f64::from(c[channel]) * ca - f64::from(r[channel]) * ra;
            signed[channel] += delta;
            abs += delta.abs();
            squared += delta * delta;
            histogram[(delta.abs().round() as usize).min(255)] += 1;
        }
    }
    let samples = pixels * 3;
    let target = ((samples as f64) * 0.95).ceil() as usize;
    let mut count = 0;
    let mut p95 = 0;
    for (bin, n) in histogram.into_iter().enumerate() {
        count += n;
        if count >= target {
            p95 = bin;
            break;
        }
    }
    Some(json!({
        "pixels": pixels,
        "rgb_mae": abs / samples as f64 / 255.0,
        "rgb_rmse": (squared / samples as f64).sqrt() / 255.0,
        "rgb_mean_delta": signed.map(|value| value / pixels as f64 / 255.0),
        "rgb_p95_abs_delta": p95 as f64 / 255.0,
        "alpha_mae": alpha_abs / pixels as f64,
    }))
}

pub async fn compare_reference_still(
    state: &AppState,
    args: CompareReferenceStillArgs,
) -> ToolResult {
    use photonic_core::timeline::AssetSource;
    let (sequence_id, format_index, width, height, still, source, document_id) = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some(sequence_id) = args.sequence_id.or(project.active_sequence) else {
            return ToolResult::error("no active sequence; provide sequence_id");
        };
        let Some(sequence) = project.sequences.get(&sequence_id) else {
            return ToolResult::error(format!("sequence {sequence_id} not found"));
        };
        if !sequence.color.is_legacy()
            && !matches!(
                sequence.color,
                photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
            )
        {
            return err_code(
                "ColorPipelineUnavailable",
                "managed-color comparison is not available",
            );
        }
        let Some(still) = sequence
            .reference_stills
            .iter()
            .find(|still| still.id == args.still_id)
        else {
            return ToolResult::error(format!("reference still {} not found", args.still_id));
        };
        if still.color != sequence.color || still.format_index != sequence.active_format {
            return err_code(
                "ReferenceIncompatible",
                "reference color configuration or format differs from the sequence",
            );
        }
        let source = project
            .media
            .assets
            .get(&still.image_asset)
            .map(|asset| asset.source.clone());
        (
            sequence_id,
            sequence.active_format,
            sequence.format().width,
            sequence.format().height,
            still.clone(),
            source,
            doc.id,
        )
    };
    let Some(AssetSource::File { path, rel_path }) = source else {
        return err_code(
            "ReferenceOffline",
            "reference image asset is missing or is not a file",
        );
    };
    let project_path = state.document_path.lock().unwrap().clone();
    let relative = project_path
        .as_ref()
        .and_then(|project| project.parent())
        .and_then(|dir| rel_path.map(|rel| dir.join(rel)));
    let Some(path) = relative
        .filter(|candidate| candidate.is_file())
        .or_else(|| path.is_file().then_some(path))
    else {
        return err_code("ReferenceOffline", "reference image is offline");
    };
    let bytes = match std::fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) => return err_code("ReferenceOffline", error.to_string()),
    };
    if still.image_hash.is_empty()
        || photonic_video::media::full_content_hash_bytes(&bytes) != still.image_hash
    {
        return err_code("ReferenceChanged", "reference image changed since capture");
    }
    let reference = match photonic_core::RasterImage::from_encoded(&bytes) {
        Ok(image) => image,
        Err(error) => return err_code("ReferenceInvalid", error),
    };
    if (reference.width, reference.height) != (width, height) {
        return err_code(
            "ReferenceIncompatible",
            "reference dimensions differ from the current sequence format",
        );
    }
    let revision = state.history.lock().await.revision();
    let (current_bytes, current_time, current_balance) = match render_reference_frame(
        state,
        sequence_id,
        format_index,
        args.at_ticks.unwrap_or(still.source_time.0),
        revision,
        document_id,
        if still.color.is_legacy() {
            photonic_video::graph::ir::FrameColorEncoding::LegacyLinearRec709
        } else {
            photonic_video::graph::ir::FrameColorEncoding::SrgbDisplay
        },
    )
    .await
    {
        Ok(frame) => frame,
        Err(error) => return error,
    };
    let current = match photonic_core::RasterImage::from_encoded(&current_bytes) {
        Ok(image) => image,
        Err(error) => return ToolResult::error(format!("rendered PNG is invalid: {error}")),
    };
    if (current.width, current.height) != (width, height) {
        return err_code(
            "ReferenceFrameInvalid",
            "rendered frame dimensions differ from the reference",
        );
    }
    let Some(metrics) = reference_rgb_metrics(&reference.pixels, &current.pixels) else {
        return ToolResult::error("reference and current pixels cannot be compared");
    };
    let (match_suggestion, match_unavailable_reason) = if still.color.is_legacy() {
        let suggestion =
            photonic_video::shot_match::suggest_printer_lights(&reference.pixels, &current.pixels);
        let reason = suggestion
            .is_none()
            .then(|| "too few opaque, non-clipped Legacy SDR samples".to_string());
        (suggestion, reason)
    } else {
        let result = (|| -> Result<_, String> {
            let reference = still
                .native_balance
                .as_ref()
                .ok_or("reference has no scene-linear balance measurement; capture it again")?;
            reference
                .validate_for_image(&still.image_hash, width, height)
                .map_err(str::to_string)?;
            let current=current_balance.as_ref().ok_or("current frame has too few eligible scene-linear samples or exceeds the analysis bound")?;
            photonic_video::native_shot_match::suggest_native_printer_lights(
                &reference.summary,
                current,
            )
            .map_err(str::to_string)
        })();
        match result {
            Ok(suggestion) => (Some(suggestion), None),
            Err(reason) => (None, Some(reason)),
        }
    };
    {
        let doc = state.document.lock().await;
        let history = state.history.lock().await;
        let still_current = doc
            .timeline
            .as_ref()
            .and_then(|project| project.sequences.get(&sequence_id))
            .and_then(|sequence| {
                sequence
                    .reference_stills
                    .iter()
                    .find(|item| item.id == still.id)
            });
        if doc.id != document_id
            || history.revision() != revision
            || still_current != Some(&still)
            || *state.document_path.lock().unwrap() != project_path
        {
            return err_code(
                "RevisionConflict",
                "project or reference changed during comparison",
            );
        }
    }
    match photonic_video::media::full_content_hash(&path) {
        Ok(hash) if hash == still.image_hash => {}
        _ => {
            return err_code(
                "ReferenceChanged",
                "reference image changed during comparison",
            )
        }
    }
    ToolResult::text("Compared reference still").with_data(json!({
        "sequence_id": sequence_id,
        "still_id": still.id,
        "reference_time_ticks": still.source_time.0,
        "reference_revision": still.grade_revision,
        "current_time_ticks": current_time.0,
        "current_revision": revision,
        "interpretation": if still.color.is_legacy() { "legacy_sdr_srgb_rgba8_over_black" } else { "native_managed_srgb_rgba8_over_black" },
        "metrics": metrics,
        "shot_match_suggestion": match_suggestion,
        "shot_match_unavailable_reason": match_unavailable_reason,
    }))
}

pub async fn apply_shot_match(state: &AppState, args: ApplyShotMatchArgs) -> ToolResult {
    let comparison = compare_reference_still(
        state,
        CompareReferenceStillArgs {
            sequence_id: args.sequence_id,
            still_id: args.still_id,
            at_ticks: Some(args.at_ticks),
        },
    )
    .await;
    if comparison.is_error == Some(true) {
        return comparison;
    }
    let Some(data) = comparison.structured_content.as_ref() else {
        return ToolResult::error("shot-match comparison has no data");
    };
    if data["current_revision"] != json!(args.expected_revision)
        || data["current_time_ticks"] != json!(args.at_ticks)
    {
        return err_code(
            "RevisionConflict",
            "shot-match preview is stale; compare again",
        );
    }
    let Some(suggestion) = data["shot_match_suggestion"].as_object() else {
        return err_code(
            "MatchUnavailable",
            data["shot_match_unavailable_reason"]
                .as_str()
                .unwrap_or("the frame has too few usable pixels for a global match"),
        );
    };
    let points: [f32; 3] =
        match serde_json::from_value(suggestion.get("points").cloned().unwrap_or(Value::Null)) {
            Ok(points) => points,
            Err(_) => return ToolResult::error("shot-match suggestion has invalid points"),
        };
    let sequence_id: SequenceId = match serde_json::from_value(data["sequence_id"].clone()) {
        Ok(id) => id,
        Err(_) => return ToolResult::error("shot-match comparison has no sequence"),
    };
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    if history.revision() != args.expected_revision {
        return err_code("RevisionConflict", "project changed during shot match");
    }
    let Some(project) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((owner_sequence, track_id)) = locate_clip(project, args.clip_id) else {
        return ToolResult::error(format!("clip {} not found", args.clip_id));
    };
    if owner_sequence != sequence_id {
        return err_code(
            "MatchUnavailable",
            "target clip is not in the compared sequence",
        );
    }
    let Some(sequence) = project.sequences.get(&sequence_id) else {
        return ToolResult::error("compared sequence disappeared");
    };
    let visible: Vec<_> = sequence
        .video_tracks
        .iter()
        .filter(|track| track.enabled)
        .flat_map(|track| &track.clips)
        .filter(|clip| {
            clip.enabled && clip.start.0 <= args.at_ticks && args.at_ticks < clip.end().0
        })
        .collect();
    if visible.len() != 1 || visible[0].id != args.clip_id {
        return err_code(
            "MatchUnavailable",
            "apply requires the target to be the only visible video clip at the compared time",
        );
    }
    let Some(target) = sequence
        .track(track_id)
        .and_then(|track| track.clips.iter().find(|clip| clip.id == args.clip_id))
    else {
        return ToolResult::error("target clip disappeared");
    };
    let mut grade = target.grade.clone().unwrap_or_default();
    if grade.bypass {
        return err_code(
            "MatchUnavailable",
            "target grade is bypassed; enable it before applying a shot match",
        );
    }
    let op = GradeOp::new(
        GradeOpKind::PrinterLights,
        GradeOpParams::PrinterLights { points },
    );
    let op_id = op.id;
    if grade.graph.is_some() {
        if let Err(error) = grade.add_graph_corrector(op, false) {
            return ToolResult::error(error);
        }
    } else {
        grade.ops.push(op);
    }
    let command = match ops::set_grade(project, sequence_id, track_id, args.clip_id, Some(grade)) {
        Ok(command) => command,
        Err(error) => return map_edit_error(error),
    };
    history.execute_discrete(Command::Timeline(command), &mut doc);
    ToolResult::text("Applied editable shot-match correction").with_data(json!({
        "sequence_id": sequence_id,
        "clip_id": args.clip_id,
        "still_id": args.still_id,
        "op_id": op_id,
        "points": points,
        "revision": history.revision(),
        "method": suggestion.get("method"),
    }))
}

pub async fn apply_lut(state: &AppState, args: ApplyLutArgs) -> ToolResult {
    tracing::debug!("tool: apply_lut {}", args.clip_id);
    // Validate + resolve the LUT file up front (outside the doc lock).
    let lut_asset: Option<(AssetId, TimelineCmd)> = match &args.lut_path {
        None => None,
        Some(path) => {
            let pb =
                match crate::path_guard::check_path(state, path, photonic_core::PathAccess::Read) {
                    Ok(p) => p,
                    Err(e) => return e,
                };
            if !pb.exists() {
                return err_code("AssetOffline", format!("LUT file not found: {path}"));
            }
            let bytes = match std::fs::read(&pb) {
                Ok(bytes) => bytes,
                Err(e) => return ToolResult::error(format!("could not read LUT: {e}")),
            };
            let src = match std::str::from_utf8(&bytes) {
                Ok(src) => src,
                Err(e) => return ToolResult::error(format!("invalid .cube LUT encoding: {e}")),
            };
            if let Err(e) = photonic_render::parse_cube(src) {
                return ToolResult::error(format!("invalid .cube LUT: {e}"));
            }
            let mut asset = photonic_core::timeline::MediaAsset::from_file(AssetKind::Lut3d, pb);
            asset.lut_color =
                Some(photonic_core::timeline::color::LutColorInterpretation::legacy_creative());
            asset.lut_full_hash = Some(photonic_video::media::full_content_hash_bytes(&bytes));
            let id = asset.id;
            Some((id, ops::add_asset(asset)))
        }
    };

    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((seq_id, track_id)) = locate_clip(p, args.clip_id) else {
        return ToolResult::error(format!("clip {} not found", args.clip_id));
    };
    let clip = find_clip(p, seq_id, track_id, args.clip_id).unwrap();
    let mut grade = clip.grade.clone().unwrap_or_default();
    if grade.graph.is_some() {
        return ToolResult::error(
            "apply_lut cannot rewrite a grading graph; edit its LUT corrector through set_grade",
        );
    }
    // Drop any existing LUT op(s) — a clip carries at most one LUT in this tool.
    grade.ops.retain(|o| o.kind != GradeOpKind::Lut3d);
    let mut cmds = Vec::new();
    if let Some((asset_id, add_cmd)) = &lut_asset {
        cmds.push(add_cmd.clone());
        let op = GradeOp::new(
            GradeOpKind::Lut3d,
            GradeOpParams::Lut3d {
                asset: *asset_id,
                intensity: args.intensity.unwrap_or(1.0).clamp(0.0, 1.0),
                interp: photonic_core::timeline::LutInterp::Trilinear,
            },
        );
        grade.ops.push(op);
    }
    let new_grade = if grade.ops.is_empty() {
        None
    } else {
        Some(grade)
    };
    match ops::set_grade(p, seq_id, track_id, args.clip_id, new_grade) {
        Ok(set_cmd) => {
            cmds.push(set_cmd);
            history.execute_discrete(batch_or_single(cmds), &mut doc);
            if lut_asset.is_some() {
                ToolResult::text("Applied LUT to clip grade")
            } else {
                ToolResult::text("Removed LUT from clip grade")
            }
        }
        Err(e) => map_edit_error(e),
    }
}

pub async fn copy_grade(state: &AppState, args: CopyGradeArgs) -> ToolResult {
    tracing::debug!(
        "tool: copy_grade {} -> {} target(s)",
        args.source_clip_id,
        args.target_clip_ids.len()
    );
    let mut doc = state.document.lock().await;
    let mut history = state.history.lock().await;
    if args.target_clip_ids.is_empty() {
        return ToolResult::error("no target clips given");
    }
    let mut unique_targets = std::collections::HashSet::new();
    for target in &args.target_clip_ids {
        if *target == args.source_clip_id {
            return ToolResult::error("source clip cannot also be a target");
        }
        if !unique_targets.insert(*target) {
            return ToolResult::error(format!("duplicate target clip {target}"));
        }
    }
    let Some(p) = doc.timeline.as_ref() else {
        return ToolResult::error("no timeline project");
    };
    let Some((s_seq, s_track)) = locate_clip(p, args.source_clip_id) else {
        return ToolResult::error(format!("source clip {} not found", args.source_clip_id));
    };
    let mut cmds = Vec::new();
    let mut applied = 0usize;
    for target in &args.target_clip_ids {
        let Some((seq_id, track_id)) = locate_clip(p, *target) else {
            return ToolResult::error(format!("target clip {target} not found"));
        };
        match ops::copy_grade_correctors(
            p,
            (s_seq, s_track, args.source_clip_id),
            (seq_id, track_id, *target),
            args.op_ids.as_deref(),
            args.append,
        ) {
            Ok(cmd) => {
                cmds.push(Command::Timeline(cmd));
                applied += 1;
            }
            Err(e) => return map_edit_error(e),
        }
    }
    history.execute_discrete(Command::Batch(cmds), &mut doc);
    ToolResult::text(format!("Copied grade to {applied} clip(s)"))
}

fn grade_presets_path() -> Option<std::path::PathBuf> {
    export_presets::config_dir().map(|d| d.join("grade_presets.json"))
}

fn load_grade_presets() -> std::collections::BTreeMap<String, Grade> {
    let Some(path) = grade_presets_path() else {
        return Default::default();
    };
    std::fs::read(&path)
        .ok()
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default()
}

fn save_grade_presets(map: &std::collections::BTreeMap<String, Grade>) -> Result<(), String> {
    let Some(path) = grade_presets_path() else {
        return Err("no config directory available".into());
    };
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
    }
    let bytes = serde_json::to_vec_pretty(map).map_err(|e| e.to_string())?;
    std::fs::write(&path, bytes).map_err(|e| e.to_string())
}

pub async fn grade_preset(state: &AppState, args: GradePresetArgs) -> ToolResult {
    tracing::debug!("tool: grade_preset");
    match args.op {
        GradePresetOp::List => {
            let names: Vec<String> = load_grade_presets().into_keys().collect();
            ToolResult::text(format!("{} grade preset(s)", names.len()))
                .with_data(json!({ "presets": names }))
        }
        GradePresetOp::Save => {
            let (Some(clip_id), Some(name)) = (args.clip_id, args.name.clone()) else {
                return ToolResult::error("save requires clip_id and name");
            };
            let doc = state.document.lock().await;
            let Some(p) = doc.timeline.as_ref() else {
                return ToolResult::error("no timeline project");
            };
            let Some((seq_id, track_id)) = locate_clip(p, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            let Some(grade) = find_clip(p, seq_id, track_id, clip_id).and_then(|c| c.grade.clone())
            else {
                return ToolResult::error("clip has no grade to save");
            };
            drop(doc);
            let mut map = load_grade_presets();
            map.insert(name.clone(), grade);
            if let Err(e) = save_grade_presets(&map) {
                return ToolResult::error(format!("could not save preset: {e}"));
            }
            ToolResult::text(format!("Saved grade preset {name:?}"))
        }
        GradePresetOp::Apply => {
            let (Some(clip_id), Some(name)) = (args.clip_id, args.name.clone()) else {
                return ToolResult::error("apply requires clip_id and name");
            };
            let map = load_grade_presets();
            let Some(grade) = map.get(&name).cloned() else {
                return ToolResult::error(format!("no grade preset named {name:?}"));
            };
            let mut doc = state.document.lock().await;
            let mut history = state.history.lock().await;
            let Some(p) = doc.timeline.as_ref() else {
                return ToolResult::error("no timeline project");
            };
            let Some((seq_id, track_id)) = locate_clip(p, clip_id) else {
                return ToolResult::error(format!("clip {clip_id} not found"));
            };
            match ops::set_grade(p, seq_id, track_id, clip_id, Some(grade)) {
                Ok(cmd) => {
                    history.execute_discrete(Command::Timeline(cmd), &mut doc);
                    ToolResult::text(format!("Applied grade preset {name:?}"))
                }
                Err(e) => map_edit_error(e),
            }
        }
    }
}

/// Queue one exact scope measurement without keeping a tool request open.
/// Cancellation is cooperative at the frame boundary; GPU readback and scope
/// binning finish before their resources and admission slot are released.
pub async fn measure_scopes(state: &AppState, args: GetScopesArgs) -> ToolResult {
    let expected_revision = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some((sequence, _)) = locate_clip(project, args.clip_id) else {
            return ToolResult::error(format!("clip {} not found", args.clip_id));
        };
        if let Err(error) = resolve_tick(
            args.at_ticks,
            args.at_tc.as_deref(),
            args.at_seconds,
            Some(project.sequences[&sequence].frame_rate),
        ) {
            return error;
        }
        state.history.lock().await.revision()
    };
    let (job_id, cancel) = match state.video_jobs.lock() {
        Ok(mut jobs) => match jobs.start("measure_scopes") {
            Ok(job) => job,
            Err(error) => {
                return ToolResult::error_with_code("JobCapacityExceeded", error.to_string())
            }
        },
        Err(_) => return ToolResult::error("scope job registry unavailable"),
    };
    let worker_state = state.clone();
    let jobs = std::sync::Arc::clone(&state.video_jobs);
    tokio::spawn(async move {
        set_job_status(
            &jobs,
            job_id,
            JobStatus::Running {
                progress: 0.0,
                message: "rendering and measuring scopes".into(),
            },
        );
        let worker_cancel = std::sync::Arc::clone(&cancel);
        let result = tokio::task::spawn_blocking(move || {
            if worker_cancel.load(Ordering::Relaxed) {
                return None;
            }
            let runtime = match tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
            {
                Ok(runtime) => runtime,
                Err(error) => {
                    return Some(ToolResult::error_with_code(
                        "ScopeWorkerUnavailable",
                        error.to_string(),
                    ))
                }
            };
            Some(runtime.block_on(get_scopes(&worker_state, args)))
        })
        .await;
        let status = if cancel.load(Ordering::Relaxed) {
            JobStatus::Cancelled
        } else {
            match result {
                Ok(Some(result)) => {
                    let data = result.structured_content.unwrap_or_default();
                    if result.is_error == Some(true) {
                        JobStatus::Failed {
                            error_code: data["error_code"]
                                .as_str()
                                .unwrap_or("ScopeMeasurementFailed")
                                .into(),
                            message: data["message"]
                                .as_str()
                                .unwrap_or("Scope measurement failed")
                                .into(),
                        }
                    } else if data["revision"] != json!(expected_revision) {
                        JobStatus::Failed {
                            error_code: "RevisionConflict".into(),
                            message: "Document changed before scope measurement; request a new job"
                                .into(),
                        }
                    } else {
                        JobStatus::Done { result: data }
                    }
                }
                Ok(None) => JobStatus::Cancelled,
                Err(error) => JobStatus::Failed {
                    error_code: "ScopeWorkerFailed".into(),
                    message: error.to_string(),
                },
            }
        };
        set_job_status(&jobs, job_id, status);
    });
    ToolResult::text("Scope measurement queued; inspect with get_job_status or cancel_job")
        .with_data(json!({ "job_id": job_id, "expected_revision": expected_revision }))
}

/// GUI/MCP share the actual key shader and exact frame input; this is read-only.
async fn correction_input_location(
    state: &AppState,
    clip_id: ClipId,
    op_id: photonic_core::timeline::GradeOpId,
    graph_node_id: Option<u32>,
    stage: photonic_core::timeline::GradeInspectionStage,
) -> Result<
    (
        SequenceId,
        FrameRate,
        bool,
        photonic_core::timeline::GradeOpKind,
        u64,
        uuid::Uuid,
    ),
    ToolResult,
> {
    let doc = state.document.lock().await;
    let Some(project) = doc.timeline.as_ref() else {
        return Err(ToolResult::error("no timeline project"));
    };
    let Some((sequence, track)) = locate_clip(project, clip_id) else {
        return Err(ToolResult::error("clip not found"));
    };
    let sequence_data = &project.sequences[&sequence];
    let clip = sequence_data
        .track(track)
        .unwrap()
        .clips
        .iter()
        .find(|clip| clip.id == clip_id)
        .unwrap();
    let Some(grade) = stage
        .resolve_grade(project, clip)
        .filter(|grade| !grade.bypass)
    else {
        return Err(err_code(
            "QualifierInputUnavailable",
            "inspection requires an enabled selected grade stage",
        ));
    };
    let native = !sequence_data.color.is_legacy();
    if stage != photonic_core::timeline::GradeInspectionStage::Clip
        && !matches!(
            sequence_data.color,
            photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
        )
    {
        return Err(err_code(
            "GradeInputUnavailable",
            "non-clip stage input inspection requires Native Managed color",
        ));
    }
    let graph_input_valid = if graph_node_id.is_some() || grade.graph.is_some() {
        native && grade.has_grade_input(op_id, graph_node_id)
    } else {
        true
    };
    if !graph_input_valid {
        return Err(err_code("GradeInputUnavailable", "graph inspection requires Native Managed and a matching corrector/key-source node; specify graph_node_id when an operator has multiple image instances"));
    }
    let Some(op) = grade.ops.iter().find(|op| op.id == op_id && op.enabled) else {
        return Err(err_code(
            "QualifierInputUnavailable",
            "the selected corrector is not enabled",
        ));
    };
    Ok((
        sequence,
        sequence_data.frame_rate,
        !sequence_data.color.is_legacy(),
        op.kind,
        state.history.lock().await.revision(),
        doc.id,
    ))
}

pub async fn sample_grade_input(state: &AppState, args: SampleGradeInputArgs) -> ToolResult {
    if ![args.x, args.y]
        .into_iter()
        .all(|v| v.is_finite() && (0.0..=1.0).contains(&v))
    {
        return err_code(
            "InvalidSampleCoordinates",
            "x/y must be finite normalized coordinates in [0,1]",
        );
    }
    let stage = args.stage.unwrap_or_default();
    let (sequence, frame_rate, native, kind, revision, document_id) =
        match correction_input_location(state, args.clip_id, args.op_id, args.graph_node_id, stage)
            .await
        {
            Ok(location) => location,
            Err(error) => return error,
        };
    if !native {
        return err_code(
            "GradeInputUnavailable",
            "this sampler requires Native Managed input coordinates",
        );
    }
    let point = if stage != photonic_core::timeline::GradeInspectionStage::Clip {
        if !matches!(
            kind,
            photonic_core::timeline::GradeOpKind::Curves
                | photonic_core::timeline::GradeOpKind::HslQualifier
        ) {
            return err_code(
                "GradeInputUnavailable",
                "sampling supports curve and qualifier inputs",
            );
        }
        ScopeTapPoint::GradeStageInput {
            clip: args.clip_id,
            stage,
            node: args.graph_node_id,
            op: args.op_id,
        }
    } else {
        match (kind, args.graph_node_id) {
        (photonic_core::timeline::GradeOpKind::Curves, Some(node)) => ScopeTapPoint::NativeGraphCurveInput { clip: args.clip_id, node, op: args.op_id },
        (photonic_core::timeline::GradeOpKind::HslQualifier, Some(node)) => ScopeTapPoint::NativeGraphQualifierInput { clip: args.clip_id, node, op: args.op_id },
        (photonic_core::timeline::GradeOpKind::Curves, None) => ScopeTapPoint::NativeCurveInput {
            clip: args.clip_id,
            op: args.op_id,
        },
        (photonic_core::timeline::GradeOpKind::HslQualifier, None) => ScopeTapPoint::NativeQualifierInput {
            clip: args.clip_id,
            op: args.op_id,
        },
        _ => {
            return err_code(
                "GradeInputUnavailable",
                "sampling supports native clip curves and qualifiers with an unambiguous corrector input",
            )
        }
    }
    };
    let time = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(frame_rate),
    ) {
        Ok(time) => time,
        Err(error) => return error,
    };
    let measurement = match render_tap_pixels_mode(
        state,
        sequence,
        time,
        args.format_index,
        point,
        ScopeReadbackMode::NativeLogInput,
    )
    .await
    {
        Ok(value) => value,
        Err(error) => return error,
    };
    if measurement.revision != revision
        || state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during selected-stage input inspection",
        );
    }
    let x = ((args.x * f64::from(measurement.width)).floor() as u32).min(measurement.width - 1);
    let y = ((args.y * f64::from(measurement.height)).floor() as u32).min(measurement.height - 1);
    let Some(pixel) = measurement
        .pixels
        .get(y as usize * measurement.width as usize + x as usize)
    else {
        return err_code("GradeInputUnavailable", "incomplete input readback");
    };
    if !pixel.iter().all(|v| v.is_finite()) || pixel[3] <= 0.0 {
        return err_code(
            "NoSampleCoverage",
            "the sampled pixel has no finite source coverage",
        );
    }
    let rgb = export_convert::unpremultiply([pixel[0], pixel[1], pixel[2]], pixel[3])
        .map(|v| v.clamp(0.0, 1.0));
    let luma = rgb[0] * 0.27222872 + rgb[1] * 0.67408174 + rgb[2] * 0.053689517;
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed while presenting selected-stage input",
        );
    }
    ToolResult::text("Native correction input sample").with_data(json!({
        "stage":stage,"clip_id":args.clip_id,"op_id":args.op_id,"graph_node_id":args.graph_node_id,"tick":measurement.time.0,"revision":measurement.revision,"snapshot_generation":measurement.generation,
        "width":measurement.width,"height":measurement.height,"pixel":{"x":x,"y":y},"coordinates":"acescct_ap1_bounded","rgb":rgb,"ap1_log_luma":luma,"alpha":pixel[3]
    }))
}

/// Inspect a mixed/refined matte without grading, alpha division or display conversion.
pub async fn inspect_grade_matte(state: &AppState, args: InspectGradeMatteArgs) -> ToolResult {
    let stage = args.stage.unwrap_or_default();
    let (sequence, frame_rate, revision, document_id) = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return err_code("GradeMatteUnavailable", "no timeline project");
        };
        let Some((sequence, track)) = locate_clip(project, args.clip_id) else {
            return err_code("GradeMatteUnavailable", "clip not found");
        };
        let seq = &project.sequences[&sequence];
        if !matches!(
            seq.color,
            photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
        ) {
            return err_code(
                "GradeMatteUnavailable",
                "matte graph inspection requires Native Managed color",
            );
        }
        let valid = find_clip(project, sequence, track, args.clip_id)
            .and_then(|clip| stage.resolve_grade(project, clip))
            .is_some_and(|grade| grade.has_matte_output(args.graph_node_id));
        if !valid {
            return err_code(
                "GradeMatteUnavailable",
                "select a matte node in an enabled selected grade stage",
            );
        }
        (
            sequence,
            seq.frame_rate,
            state.history.lock().await.revision(),
            doc.id,
        )
    };
    let time = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(frame_rate),
    ) {
        Ok(time) => time,
        Err(error) => return error,
    };
    let measurement = match render_tap_pixels_mode(
        state,
        sequence,
        time,
        args.format_index,
        if stage == photonic_core::timeline::GradeInspectionStage::Clip {
            ScopeTapPoint::GradeGraphMatteOutput {
                clip: args.clip_id,
                node: args.graph_node_id,
            }
        } else {
            ScopeTapPoint::GradeStageGraphMatteOutput {
                clip: args.clip_id,
                stage,
                node: args.graph_node_id,
            }
        },
        ScopeReadbackMode::MatteOutput,
    )
    .await
    {
        Ok(value) => value,
        Err(error) => return error,
    };
    if measurement.revision != revision
        || state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during matte inspection",
        );
    }
    let inspection = match photonic_render::matte_inspection::inspect_weights(
        &measurement.pixels,
        measurement.width,
        measurement.height,
    ) {
        Ok(value) => value,
        Err(error) => return err_code("GradeMatteReadbackFailed", error),
    };
    let image = image::RgbaImage::from_raw(measurement.width, measurement.height, inspection.rgba)
        .expect("validated matte dimensions");
    let mut png = Vec::new();
    if let Err(error) = image.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
    {
        return ToolResult::error(error.to_string());
    }
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed while presenting matte output",
        );
    }
    ToolResult::text("Grading graph matte output")
        .with_image(general_purpose::STANDARD.encode(png))
        .with_data(json!({"stage":stage,"clip_id":args.clip_id,"graph_node_id":args.graph_node_id,
            "tick":measurement.time.0,"revision":measurement.revision,
            "snapshot_generation":measurement.generation,"width":measurement.width,"height":measurement.height,
            "matte_encoding":"unassociated_weight",
            "coverage":{"min":inspection.minimum,"max":inspection.maximum,"mean":inspection.mean}}))
}

/// Measure unclipped AP1 working values and actual SDR output from one frame.
pub async fn measure_native_output(state: &AppState, args: MeasureNativeOutputArgs) -> ToolResult {
    let (frame_rate, revision, document_id) = {
        let doc = state.document.lock().await;
        let Some(seq) = doc
            .timeline
            .as_ref()
            .and_then(|p| p.sequences.get(&args.sequence_id))
        else {
            return err_code("NativeOutputUnavailable", "sequence not found");
        };
        if !matches!(
            seq.color,
            photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
        ) {
            return err_code(
                "NativeOutputUnavailable",
                "paired output measurement requires Native Managed color",
            );
        }
        let Some(format) = seq
            .formats
            .get(args.format_index.unwrap_or(seq.active_format))
        else {
            return err_code(
                "FormatOutOfRange",
                "selected sequence format does not exist",
            );
        };
        if u64::from(format.width) * u64::from(format.height)
            > photonic_render::scene_measurement::MAX_PAIRED_PIXELS as u64
        {
            return err_code("NativeOutputTooLarge","paired output measurement supports at most 16777216 pixels; choose a smaller authored format explicitly");
        }
        (
            seq.frame_rate,
            state.history.lock().await.revision(),
            doc.id,
        )
    };
    let time = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(frame_rate),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    let mut measurement = match render_tap_pixels_mode(
        state,
        args.sequence_id,
        time,
        args.format_index,
        ScopeTapPoint::NativeSceneProgram,
        ScopeReadbackMode::ProgramOutput,
    )
    .await
    {
        Ok(m) => m,
        Err(e) => return e,
    };
    if measurement.revision != revision
        || state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during paired output measurement",
        );
    }
    let scene = std::mem::take(&mut measurement.pixels);
    let Some(display) = measurement.display_pixels.take() else {
        return err_code(
            "NativeOutputUnavailable",
            "paired display readback is absent",
        );
    };
    let (width, height) = (measurement.width, measurement.height);
    let mut measured = match tokio::task::spawn_blocking(move || {
        photonic_render::scene_measurement::measure_pair(&scene, &display, width, height)
    })
    .await
    {
        Ok(Ok(m)) => m,
        Ok(Err(e)) => return err_code("NativeOutputReadbackFailed", e),
        Err(e) => return err_code("NativeOutputReadbackFailed", e.to_string()),
    };
    let image =
        image::RgbaImage::from_raw(width, height, std::mem::take(&mut measured.display_rgba))
            .expect("validated paired image dimensions");
    let mut png = Vec::new();
    if let Err(e) = image.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png) {
        return ToolResult::error(e.to_string());
    }
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during paired output measurement",
        );
    }
    ToolResult::text("Native scene and SDR output measurements").with_image(general_purpose::STANDARD.encode(png)).with_data(json!({
        "document_id":document_id,"sequence_id":args.sequence_id,"tick":measurement.time.0,"revision":measurement.revision,"snapshot_generation":measurement.generation,"content_hash":format!("{:032x}",measurement.content_hash),"width":width,"height":height,
        "scene_encoding":"scene_linear_acescg","display_encoding":"srgb_display","measurements":measured,
        "note":"Same Full/original frame before and after the SDR transform. Straight covered pixels are equally weighted; no signal extrema or means exist when fully transparent. Relative stops describe working values, not reconstructed scene light. Luminance uses AP1 Y and stops relative to 0.18, range [-12,12); no absolute nits, HDR delivery, video IRE or calibrated-monitor claim. PNG alone is quantized and clamped for display; statistics retain readback values."
    }))
}

/// Inspect an exact scene image node through the qualified SDR display transform.
pub async fn inspect_grade_image(state: &AppState, args: InspectGradeImageArgs) -> ToolResult {
    let stage = args.stage.unwrap_or_default();
    let (sequence, frame_rate, revision, document_id) = {
        let doc = state.document.lock().await;
        let Some(project) = doc.timeline.as_ref() else {
            return err_code("GradeImageUnavailable", "no timeline project");
        };
        let Some((sequence, track)) = locate_clip(project, args.clip_id) else {
            return err_code("GradeImageUnavailable", "clip not found");
        };
        let seq = &project.sequences[&sequence];
        if !matches!(
            seq.color,
            photonic_core::timeline::color::SequenceColorConfig::NativeManaged(_)
        ) {
            return err_code(
                "GradeImageUnavailable",
                "image graph inspection requires Native Managed color",
            );
        }
        let valid = find_clip(project, sequence, track, args.clip_id)
            .and_then(|clip| stage.resolve_grade(project, clip))
            .is_some_and(|grade| grade.has_image_output(args.graph_node_id));
        if !valid {
            return err_code(
                "GradeImageUnavailable",
                "select an image node in an enabled selected grade stage",
            );
        }
        (
            sequence,
            seq.frame_rate,
            state.history.lock().await.revision(),
            doc.id,
        )
    };
    let time = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(frame_rate),
    ) {
        Ok(time) => time,
        Err(error) => return error,
    };
    let mut measurement = match render_tap_pixels_mode(
        state,
        sequence,
        time,
        args.format_index,
        if stage == photonic_core::timeline::GradeInspectionStage::Clip {
            ScopeTapPoint::GradeGraphImageOutput {
                clip: args.clip_id,
                node: args.graph_node_id,
            }
        } else {
            ScopeTapPoint::GradeStageGraphImageOutput {
                clip: args.clip_id,
                stage,
                node: args.graph_node_id,
            }
        },
        ScopeReadbackMode::ImageOutput,
    )
    .await
    {
        Ok(value) => value,
        Err(error) => return error,
    };
    if measurement.revision != revision
        || state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during image inspection",
        );
    }
    let pixels = std::mem::take(&mut measurement.pixels);
    let (width, height) = (measurement.width, measurement.height);
    let inspection = match tokio::task::spawn_blocking(move || {
        photonic_video::color::native_output::inspection::inspect_scene_image(
            &pixels, width, height,
        )
    })
    .await
    {
        Ok(Ok(value)) => value,
        Ok(Err(error)) => return err_code("GradeImageReadbackFailed", error),
        Err(error) => return err_code("GradeImageReadbackFailed", error.to_string()),
    };
    let image = image::RgbaImage::from_raw(measurement.width, measurement.height, inspection.rgba)
        .expect("validated image dimensions");
    let mut png = Vec::new();
    if let Err(error) = image.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
    {
        return ToolResult::error(error.to_string());
    }
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed while presenting the image output",
        );
    }
    ToolResult::text("Grading graph image output")
        .with_image(general_purpose::STANDARD.encode(png))
        .with_data(json!({"stage":stage,"clip_id":args.clip_id,"graph_node_id":args.graph_node_id,
            "tick":measurement.time.0,"revision":measurement.revision,
            "snapshot_generation":measurement.generation,"width":measurement.width,"height":measurement.height,
            "image_encoding":"srgb_display","scene_encoding":"scene_linear_acescg",
            "scene_rgb":{"min":inspection.scene_min,"max":inspection.scene_max},
            "coverage":{"min":inspection.alpha_min,"max":inspection.alpha_max}}))
}

pub async fn inspect_qualifier(state: &AppState, args: InspectQualifierArgs) -> ToolResult {
    let stage = args.stage.unwrap_or_default();
    let (sequence, frame_rate, native, kind, revision, document_id) =
        match correction_input_location(state, args.clip_id, args.op_id, args.graph_node_id, stage)
            .await
        {
            Ok(location) => location,
            Err(error) => return error,
        };
    if kind != photonic_core::timeline::GradeOpKind::HslQualifier {
        return err_code(
            "QualifierInputUnavailable",
            "the selected corrector is not a qualifier",
        );
    }
    let time = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(frame_rate),
    ) {
        Ok(time) => time,
        Err(error) => return error,
    };
    let point = if stage != photonic_core::timeline::GradeInspectionStage::Clip {
        ScopeTapPoint::GradeStageInput {
            clip: args.clip_id,
            stage,
            node: args.graph_node_id,
            op: args.op_id,
        }
    } else if let Some(node) = args.graph_node_id {
        ScopeTapPoint::NativeGraphQualifierInput {
            clip: args.clip_id,
            node,
            op: args.op_id,
        }
    } else if native {
        ScopeTapPoint::NativeQualifierInput {
            clip: args.clip_id,
            op: args.op_id,
        }
    } else {
        ScopeTapPoint::ClipPreGrade(args.clip_id)
    };
    let measurement = match render_tap_pixels_mode(
        state,
        sequence,
        time,
        args.format_index,
        point,
        ScopeReadbackMode::Qualifier(args.clip_id, args.op_id),
    )
    .await
    {
        Ok(result) => result,
        Err(error) => return error,
    };
    if measurement.revision != revision
        || state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed during selected-stage input inspection",
        );
    }
    if measurement.pixels.len() != measurement.width as usize * measurement.height as usize
        || measurement.pixels.is_empty()
    {
        return err_code("QualifierReadbackFailed", "incomplete key matte readback");
    }
    let mut minimum = 1.0_f32;
    let mut maximum = 0.0_f32;
    let mut sum = 0.0_f64;
    let mut rgba = Vec::with_capacity(measurement.pixels.len() * 4);
    for pixel in &measurement.pixels {
        if !pixel[0].is_finite() {
            return err_code("QualifierReadbackFailed", "non-finite key matte readback");
        }
        let value = pixel[0].clamp(0.0, 1.0);
        minimum = minimum.min(value);
        maximum = maximum.max(value);
        sum += f64::from(value);
        let code = (value * 255.0).round() as u8;
        rgba.extend_from_slice(&[code, code, code, 255]);
    }
    let image = image::RgbaImage::from_raw(measurement.width, measurement.height, rgba)
        .expect("verified matte dimensions");
    let mut png = Vec::new();
    if let Err(error) = image.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
    {
        return ToolResult::error(error.to_string());
    }
    if state.document.lock().await.id != document_id
        || state.history.lock().await.revision() != revision
    {
        return err_code(
            "RevisionConflict",
            "document changed while presenting selected-stage input",
        );
    }
    ToolResult::text("Qualifier isolation matte").with_image(general_purpose::STANDARD.encode(png)).with_data(json!({
        "stage": stage,"clip_id": args.clip_id, "op_id": args.op_id, "graph_node_id": args.graph_node_id, "tick": measurement.time.0,
        "revision": measurement.revision, "snapshot_generation": measurement.generation,
        "width": measurement.width, "height": measurement.height,
        "key_coordinates": if measurement.encoding == photonic_video::graph::ir::FrameColorEncoding::SceneLinearAcescg { "acescct_ap1_hsl" } else { "linear_rec709_hsl" },
        "matte_encoding": "coverage", "coverage": { "min": minimum, "max": maximum, "mean": sum / measurement.pixels.len() as f64 }
    }))
}

pub async fn get_scopes(state: &AppState, args: GetScopesArgs) -> ToolResult {
    tracing::debug!("tool: get_scopes {}", args.clip_id);
    // Resolve the clip's owning sequence + tick.
    let (seq_id, fr) = {
        let doc = state.document.lock().await;
        let Some(p) = doc.timeline.as_ref() else {
            return ToolResult::error("no timeline project");
        };
        let Some((seq_id, _)) = locate_clip(p, args.clip_id) else {
            return ToolResult::error(format!("clip {} not found", args.clip_id));
        };
        (seq_id, p.sequences.get(&seq_id).unwrap().frame_rate)
    };
    let t = match resolve_tick(
        args.at_ticks,
        args.at_tc.as_deref(),
        args.at_seconds,
        Some(fr),
    ) {
        Ok(t) => t,
        Err(e) => return e,
    };
    // K-E2: the scopes tap is a per-clip readback point, not the program frame.
    // `render_scope_tap_pixels` asks the engine for the clip's post-`Grade`
    // texture and reports which point it actually got, so an agent grading a
    // clip under a caption track or a second video track measures the signal it
    // is adjusting (03 §3.6 as amended by 27 A-7).
    let want = match args.tap {
        ScopeTap::Clip => ScopeTapPoint::Clip(args.clip_id),
        ScopeTap::Program => ScopeTapPoint::Program,
    };
    let measurement = match render_scope_tap_pixels(state, seq_id, t, args.format_index, want).await
    {
        Ok(v) => v,
        Err(e) => return e,
    };
    let ScopeMeasurement {
        pixels,
        width: w,
        height: h,
        tap: got,
        time: measured_time,
        revision,
        generation,
        diagnostics,
        encoding,
        ..
    } = measurement;
    if encoding == photonic_video::graph::ir::FrameColorEncoding::SceneLinearAcescg {
        let scene = match photonic_render::scene_scopes::measure(&pixels, w, h) {
            Ok(scene) => scene,
            Err(error) => return err_code("SceneScopeUnavailable", error),
        };
        let histogram = &scene.histogram;
        return ToolResult::text(format!("AP1 scene-relative scopes for {w}x{h} at tick {}", measured_time.0))
            .with_data(json!({
                "tick": measured_time.0, "requested_tick": t.0,
                "revision": revision, "snapshot_generation": generation, "sequence": seq_id,
                "width": w, "height": h, "tap": if matches!(got, ScopeTapPoint::Clip(_)) { "clip" } else { "program" },
                "color_interpretation": {"mode":"native_scene_linear", "primaries":"acescg_ap1", "scale":"relative_stops", "reference_gray":0.18, "minimum_stop":-12.0, "maximum_stop":12.0, "upper_exclusive":true},
                "histogram":{"bins":256,"luma":histogram[0],"red":histogram[1],"green":histogram[2],"blue":histogram[3]},
                "waveform":compact_waveform(&scene.waveform[0]),
                "rgb_parade":{"red":compact_waveform(&scene.waveform[1]),"green":compact_waveform(&scene.waveform[2]),"blue":compact_waveform(&scene.waveform[3])},
                "excluded":{"channel_order":["Y","R","G","B"],"transparent":scene.transparent,"invalid":scene.invalid,"nonpositive":scene.nonpositive,"below_range":scene.below,"above_range":scene.above},
                "vectorscope":null,"video_legal":null,"grading_diagnostics":diagnostics,
                "note":"Straight AP1 luminance/channels in log2(value/0.18), not nits or IRE. Positive in-range samples only; other values counted separately. Equal covered-pixel weight; spatial bins include every logical column, with at most256 measured columns. AP1 chroma vectorscope is not qualified."
            }));
    }
    let flat: Vec<f32> = pixels.iter().flat_map(|p| p.iter().copied()).collect();
    let matrix = match args.vectorscope_matrix {
        VectorscopeMatrix::Bt709 => photonic_render::color::Matrix::Bt709,
        VectorscopeMatrix::Bt601 => photonic_render::color::Matrix::Bt601,
    };
    let signal = if encoding == photonic_video::graph::ir::FrameColorEncoding::SrgbDisplay {
        photonic_render::scopes::ScopeSignal::SrgbDisplay
    } else {
        photonic_render::scopes::ScopeSignal::LegacyLinearRec709
    };
    let scopes =
        photonic_render::scopes::scopes_from_pixels_cpu_matrix_signal(&flat, w, h, matrix, signal);
    let tap_label = match got {
        ScopeTapPoint::Clip(_) => "clip",
        ScopeTapPoint::ClipPreGrade(_) => "clip_pre_grade",
        ScopeTapPoint::NativeQualifierInput { .. } => "qualifier_input",
        ScopeTapPoint::NativeCurveInput { .. } => "curve_input",
        ScopeTapPoint::NativeGraphQualifierInput { .. } => "graph_qualifier_input",
        ScopeTapPoint::NativeGraphCurveInput { .. } => "graph_curve_input",
        ScopeTapPoint::GradeGraphMatteOutput { .. } => "graph_matte_output",
        ScopeTapPoint::GradeStageGraphMatteOutput { .. } => "stage_graph_matte_output",
        ScopeTapPoint::GradeGraphImageOutput { .. } => "graph_image_output",
        ScopeTapPoint::GradeStageGraphImageOutput { .. } => "stage_graph_image_output",
        ScopeTapPoint::Program => "program",
        ScopeTapPoint::NativeSceneProgram => "native_scene_program",
        ScopeTapPoint::GradeStageInput { .. } => "grade_stage_input",
    };
    let fell_back = want != got;
    let mut data = scopes_json(&scopes, measured_time);
    data["vectorscope"]["matrix"] = json!(match args.vectorscope_matrix {
        VectorscopeMatrix::Bt709 => "bt709",
        VectorscopeMatrix::Bt601 => "bt601",
    });
    let clipping = photonic_render::scopes::clipping_cpu(&flat, w, h);
    data["clipping"] = json!({
        "domain": if signal == photonic_render::scopes::ScopeSignal::SrgbDisplay { "straight_srgb_display_before_scope_clamp" } else { "straight_linear_rec709_before_scope_clamp" },
        "below_zero_rgb": clipping.below,
        "above_reference_white_rgb": clipping.above,
    });
    let parade = photonic_render::scopes::parade_cpu_signal(&flat, w, h, signal);
    let legal: Vec<_> = parade
        .iter()
        .map(|channel| channel.video_legal_excursions())
        .collect();
    data["rgb_parade"] = json!({
        "red": compact_waveform(&parade[0]), "green": compact_waveform(&parade[1]),
        "blue": compact_waveform(&parade[2]),
    });
    data["video_legal"] = if signal == photonic_render::scopes::ScopeSignal::SrgbDisplay {
        serde_json::Value::Null
    } else {
        json!({
            "code_value_range_8bit": [16, 235],
            "below_rgb": [legal[0].0, legal[1].0, legal[2].0],
            "above_rgb": [legal[0].1, legal[1].1, legal[2].1],
            "measurement_scale": "full_0_1",
            "display_mapping": "16_to_0_percent_235_to_100_percent_clamp_excursions_to_edges",
        })
    };
    data["requested_tick"] = json!(t.0);
    data["revision"] = json!(revision);
    data["snapshot_generation"] = json!(generation);
    data["sequence"] = json!(seq_id);
    data["grading_diagnostics"] = json!(diagnostics);
    data["color_interpretation"] = if signal == photonic_render::scopes::ScopeSignal::SrgbDisplay {
        data["note"] = json!("Native Managed: display-referred sRGB component levels; chroma uses the selected luma coefficients, not calibrated BT.709 video signal");
        json!({ "mode": "native_managed_sdr", "signal_transfer": "srgb_display", "chroma_matrix": match args.vectorscope_matrix { VectorscopeMatrix::Bt709 => "bt709_coefficients", VectorscopeMatrix::Bt601 => "bt601_coefficients" }, "scale": "full_0_1" })
    } else {
        json!({ "mode": "legacy_sdr", "signal_transfer": "bt709", "matrix": "bt709", "scale": "full_0_1" })
    };
    if let Some(obj) = data.as_object_mut() {
        obj.insert("tap".into(), json!(tap_label));
        obj.insert("width".into(), json!(w));
        obj.insert("height".into(), json!(h));
        if fell_back {
            obj.insert(
                "tap_fallback_reason".into(),
                json!(
                    "the requested clip is not rendered at this tick (off its span, \
                       a disabled track, or zero opacity) — scoped the program instead"
                ),
            );
        }
    }
    let note = if fell_back {
        " (fell back from the clip tap — the clip is not in this frame)"
    } else {
        ""
    };
    ToolResult::text(format!(
        "scopes for {w}x{h} {tap_label} tap at tick {}{note}",
        measured_time.0
    ))
    .with_data(data)
}

/// Compact, agent-consumable scope payload (07 §5): full histograms plus a
/// down-sampled luma waveform (per-column brightest populated bin) and a 32×32
/// vectorscope count grid — "data, not an image" (10 §3.10).
fn scopes_json(s: &photonic_render::scopes::Scopes, t: Tick) -> serde_json::Value {
    let h = &s.histogram;
    // Waveform: for up to 256 sampled columns, the brightest populated bin.
    let cols = s.waveform.width.max(1);
    let step = cols.div_ceil(256).max(1);
    let mut luma_peaks = Vec::new();
    let mut x = 0;
    while x < cols {
        let mut top = 0usize;
        for bin in (0..s.waveform.bins).rev() {
            if (x..(x + step).min(cols)).any(|sx| s.waveform.count(sx, bin) > 0) {
                top = bin;
                break;
            }
        }
        luma_peaks.push(top as u32);
        x += step;
    }
    // Vectorscope: down-sample the 256×256 grid to 32×32 sums.
    let vs_size = s.vectorscope.size.max(1);
    const GRID: usize = 32;
    let mut vs = vec![0u32; GRID * GRID];
    for cr in 0..vs_size {
        for cb in 0..vs_size {
            let c = s.vectorscope.count(cb, cr);
            if c > 0 {
                let gr = cr * GRID / vs_size;
                let gb = cb * GRID / vs_size;
                vs[gr * GRID + gb] += c;
            }
        }
    }
    json!({
        "tick": t.0,
        "histogram": {
            "bins": h.luma.len(),
            "luma": h.luma.to_vec(), "red": h.red.to_vec(),
            "green": h.green.to_vec(), "blue": h.blue.to_vec(),
        },
        "waveform": {
            "columns": luma_peaks.len(),
            "bins": s.waveform.bins,
            "luma_peaks": luma_peaks,
        },
        "vectorscope": { "grid": GRID, "counts": vs },
        "note": "Legacy SDR: straight RGB encoded with BT.709 OETF, full-range 0..1; waveform peaks include every source column in each display column",
    })
}

/// Bounded spatial scope payload: all source samples contribute, with bins
/// and columns aggregated into a 64 × 64 grid instead of sampling columns.
fn compact_waveform(waveform: &photonic_render::scopes::Waveform) -> serde_json::Value {
    let columns = waveform.width.clamp(1, 64);
    let bins = 64;
    let mut counts = vec![0u64; columns * bins];
    for x in 0..waveform.width {
        for level in 0..waveform.bins {
            let column = x * columns / waveform.width;
            let bin = level * bins / waveform.bins;
            counts[column * bins + bin] += u64::from(waveform.count(x, level));
        }
    }
    json!({ "columns": columns, "bins": bins, "layout": "column_major", "counts": counts })
}

struct ScopeMeasurement {
    display_pixels: Option<Vec<[f32; 4]>>,
    content_hash: u128,
    pixels: Vec<[f32; 4]>,
    width: u32,
    height: u32,
    tap: ScopeTapPoint,
    time: Tick,
    revision: u64,
    generation: u64,
    diagnostics: Vec<photonic_render::grade::GradeDiagnostic>,
    encoding: photonic_video::graph::ir::FrameColorEncoding,
}

/// K-E2: render one frame headlessly and read back the **scope tap** —
/// `want` resolved against that frame's graph, which is `ScopeTapPoint::Program`
/// whenever the requested clip is not in the frame (13 §10.2). Returns the
/// pixels, their logical size (the pooled texture is bucket-padded, so the
/// frame's own logical dims are used, never the texture's) and the point that
/// actually produced them.
///
/// This costs no second render: the tap names a node the same evaluation
/// already produced (see `Evaluator::evaluate_with_tap`). What it does cost is
/// the same seek-and-wait transaction `render_frame_at` pays, so it stays behind
/// the transport lock like every other engine read.
async fn render_scope_tap_pixels(
    state: &AppState,
    seq_id: SequenceId,
    t: Tick,
    format_index: Option<usize>,
    want: ScopeTapPoint,
) -> Result<ScopeMeasurement, ToolResult> {
    render_tap_pixels_mode(
        state,
        seq_id,
        t,
        format_index,
        want,
        ScopeReadbackMode::Signal,
    )
    .await
}

#[derive(Clone, Copy)]
enum ScopeReadbackMode {
    Signal,
    Qualifier(ClipId, photonic_core::timeline::GradeOpId),
    NativeLogInput,
    MatteOutput,
    ImageOutput,
    ProgramOutput,
}

async fn render_tap_pixels_mode(
    state: &AppState,
    seq_id: SequenceId,
    t: Tick,
    format_index: Option<usize>,
    want: ScopeTapPoint,
    mode: ScopeReadbackMode,
) -> Result<ScopeMeasurement, ToolResult> {
    let qualifier = match mode {
        ScopeReadbackMode::Qualifier(clip, op) => Some((clip, op)),
        _ => None,
    };
    let bridge = engine_bridge(state)?;
    let (fr, formats, active_format) = sequence_render_info(state, seq_id).await?;
    if let Some(fi) = format_index {
        if fi >= formats.len() {
            return Err(ToolResult::error(format!(
                "format_index {fi} out of range — sequence has {} format(s)",
                formats.len()
            )));
        }
    }
    let fi = format_index
        .unwrap_or(active_format)
        .min(formats.len().saturating_sub(1));
    if t.0 < 0 {
        return Err(err_code("TickOutOfRange", "tick must be >= 0"));
    }
    let snapped = fr.frame_start(fr.frame_at(t));

    let _transport = bridge.lock_transport().await;
    bridge.sync_with_format(state, Some((seq_id, fi))).await;
    if !bridge.wait_engine_synced(Duration::from_secs(10)).await {
        return Err(ToolResult::error(
            "engine did not pick up the document snapshot within 10s",
        ));
    }
    let _settings = RenderSettingsGuard {
        session: bridge.session(),
        proxy_mode: bridge.proxy_mode(),
        preview_quality: bridge.session().requested_preview_quality(),
        scope_tap: Some(bridge.session().status().scope_tap),
    };
    let prev = bridge.session().latest_frame();
    let request_id = bridge.next_inspection_id();
    if !bridge.session().send(EngineCmd::InspectFrame {
        request_id,
        sequence: seq_id,
        time: snapped,
        proxy_mode: ProxyMode::ForceOriginal,
        quality: PreviewQuality::Full,
        scope_tap: want,
    }) {
        return Err(
            err_code("EngineBusy", "Engine command queue is full or closed")
                .with_data(json!({"retryable":true})),
        );
    }
    let frame = bridge
        .wait_fresh_frame(prev, Duration::from_secs(30), |f| {
            f.time == snapped
                && f.sequence == seq_id
                && f.preview_quality == PreviewQuality::Full
                && f.snapshot_generation == bridge.snapshot_generation()
                && f.inspection_request_id == Some(request_id)
                && f.proxy_mode == ProxyMode::ForceOriginal
        })
        .await;
    let Some(frame) = frame else {
        return Err(ToolResult::error(
            "engine did not produce the requested frame within 30s",
        ));
    };
    if !frame.color_errors.is_empty() {
        return Err(err_code(
            "ColorPipelineUnavailable",
            frame.color_errors.join("; "),
        ));
    }
    let Some(tap) = frame.scope_tap.as_ref() else {
        return Err(err_code(
            "NoScopeSignal",
            "the sequence renders nothing at this tick — there is no signal to scope",
        ));
    };
    if matches!(mode, ScopeReadbackMode::Signal) {
        validate_scope_tap_encoding(frame.scope_tap_encoding)?;
    } else if frame.scope_tap_point != want || !frame.grading_errors.is_empty() {
        return Err(if matches!(mode, ScopeReadbackMode::MatteOutput) {
            err_code(
                "GradeMatteUnavailable",
                "the requested matte output is inactive or has unresolved grading dependencies",
            )
        } else if matches!(mode, ScopeReadbackMode::ProgramOutput) {
            err_code(
                "NativeOutputUnavailable",
                "requested scene output is missing or has unresolved grading dependencies",
            )
        } else if matches!(mode, ScopeReadbackMode::ImageOutput) {
            err_code(
                "GradeImageUnavailable",
                "the requested image output is inactive or has unresolved grading dependencies",
            )
        } else {
            err_code(
                "QualifierInputUnavailable",
                "the requested key input is inactive or has unresolved grading dependencies",
            )
        });
    }

    if matches!(mode, ScopeReadbackMode::MatteOutput) {
        let valid = frame.scope_tap_encoding
            == Some(photonic_video::graph::ir::FrameColorEncoding::MatteWeight)
            && match want {
                ScopeTapPoint::GradeGraphMatteOutput { clip, node } => frame
                    .native_graph_mattes
                    .iter()
                    .any(|(c, n, _)| *c == clip && *n == node),
                ScopeTapPoint::GradeStageGraphMatteOutput { clip, stage, node } => {
                    photonic_video::graph::compile::GradeGraphStageOutput::find(
                        &frame.native_stage_graph_outputs,
                        clip,
                        stage,
                        node,
                        false,
                    )
                    .is_some()
                }
                _ => false,
            };
        if !valid {
            return Err(err_code(
                "GradeMatteUnavailable",
                "requested matte output is inactive, unreachable or unqualified",
            ));
        }
    }

    if matches!(mode, ScopeReadbackMode::ProgramOutput) {
        use photonic_video::graph::ir::FrameColorEncoding;
        if u64::from(tap.width) * u64::from(tap.height)
            > photonic_render::scene_measurement::MAX_PAIRED_PIXELS as u64
        {
            return Err(err_code(
                "NativeOutputTooLarge",
                "rendered paired output exceeds the readback pixel bound",
            ));
        }
        if want != ScopeTapPoint::NativeSceneProgram
            || frame.scope_tap_encoding != Some(FrameColorEncoding::SceneLinearAcescg)
            || frame.output_encoding != FrameColorEncoding::SrgbDisplay
            || frame.preview_asset.is_some()
            || frame.cached_preview
            || frame.logical_size != (tap.width, tap.height)
        {
            return Err(err_code(
                "NativeOutputUnavailable",
                "paired native scene and SDR output require one qualified full program frame",
            ));
        }
    }

    if matches!(mode, ScopeReadbackMode::ImageOutput) {
        let valid = frame.scope_tap_encoding
            == Some(photonic_video::graph::ir::FrameColorEncoding::SceneLinearAcescg)
            && match want {
                ScopeTapPoint::GradeGraphImageOutput { clip, node } => frame
                    .native_graph_images
                    .iter()
                    .any(|(c, n, _)| *c == clip && *n == node),
                ScopeTapPoint::GradeStageGraphImageOutput { clip, stage, node } => {
                    photonic_video::graph::compile::GradeGraphStageOutput::find(
                        &frame.native_stage_graph_outputs,
                        clip,
                        stage,
                        node,
                        true,
                    )
                    .is_some()
                }
                _ => false,
            };
        if !valid {
            return Err(err_code(
                "GradeImageUnavailable",
                "requested image output is inactive, unreachable or unqualified",
            ));
        }
    }

    if matches!(mode, ScopeReadbackMode::NativeLogInput) {
        let valid = frame.scope_tap_encoding
            == Some(photonic_video::graph::ir::FrameColorEncoding::SceneLinearAcescg)
            && match want {
                ScopeTapPoint::GradeStageInput {
                    clip,
                    stage,
                    node,
                    op,
                } => photonic_video::graph::compile::NativeStageGradeInput::find(
                    &frame.native_stage_grade_inputs,
                    clip,
                    stage,
                    node,
                    op,
                )
                .is_some(),
                ScopeTapPoint::NativeGraphCurveInput { clip, node, op } => frame
                    .native_graph_curve_inputs
                    .iter()
                    .any(|(c, id, o, _)| *c == clip && *id == node && *o == op),
                ScopeTapPoint::NativeGraphQualifierInput { clip, node, op } => frame
                    .native_graph_qualifier_inspections
                    .iter()
                    .any(|(id, key)| *id == node && key.clip == clip && key.op == op),
                ScopeTapPoint::NativeCurveInput { clip, op } => frame
                    .native_curve_inputs
                    .iter()
                    .any(|(c, o, _)| *c == clip && *o == op),
                ScopeTapPoint::NativeQualifierInput { clip, op } => frame
                    .native_qualifier_inspections
                    .iter()
                    .any(|key| key.clip == clip && key.op == op),
                _ => false,
            };
        if !valid {
            return Err(err_code(
                "GradeInputUnavailable",
                "the corrector does not have a qualified native input",
            ));
        }
    }
    let gpu = bridge.engine().gpu().clone();
    let texture = std::sync::Arc::clone(&tap.texture);
    let (width, height) = (tap.width, tap.height);
    let native_key = qualifier.and_then(|(clip, op)| {
        if let ScopeTapPoint::GradeStageInput { stage, node, .. } = want {
            return photonic_video::graph::compile::NativeStageGradeInput::find(
                &frame.native_stage_grade_inputs,
                clip,
                stage,
                node,
                op,
            )
            .and_then(|input| input.qualifier.clone());
        }
        if let ScopeTapPoint::NativeGraphQualifierInput { node, .. } = want {
            return frame
                .native_graph_qualifier_inspections
                .iter()
                .find(|(id, key)| *id == node && key.clip == clip && key.op == op)
                .map(|(_, key)| key.clone());
        }
        frame
            .native_qualifier_inspections
            .iter()
            .find(|key| key.clip == clip && key.op == op)
            .cloned()
    });
    let legacy_key = qualifier.and_then(|(clip, op)| {
        frame
            .clip_grade_inspections
            .iter()
            .find(|key| key.clip == clip)
            .and_then(|key| {
                key.ops.iter().position(|(id, _)| *id == op).map(|index| {
                    (
                        key.ops.iter().map(|(_, op)| op.clone()).collect::<Vec<_>>(),
                        index,
                    )
                })
            })
    });
    if qualifier.is_some() {
        use photonic_video::graph::ir::FrameColorEncoding;
        let valid = match frame.scope_tap_encoding {
            Some(FrameColorEncoding::SceneLinearAcescg) => native_key.is_some(),
            Some(FrameColorEncoding::LegacyLinearRec709) => legacy_key.is_some(),
            _ => false,
        };
        if !valid {
            return Err(err_code(
                "QualifierInputUnavailable",
                "the key does not have a qualified grading input",
            ));
        }
    }
    let pixels = tokio::task::spawn_blocking(move || -> Result<_, String> {
        if matches!(mode, ScopeReadbackMode::NativeLogInput) {
            let encoded = photonic_render::native_transfer::NativeAcescctPass::new(gpu.device())
                .apply(
                    gpu.device(),
                    gpu.queue(),
                    &texture,
                    photonic_render::native_transfer::AcescctDirection::Encode,
                );
            Ok(read_texture_rgba16f(&gpu, &encoded, width, height))
        } else if let Some(key) = native_key {
            let matte = photonic_render::grade_gpu::native_qualifier_matte_with_spatial_gpu(
                gpu.device(),
                gpu.queue(),
                &texture,
                &key.qualifier,
                key.mask.as_ref(),
                (width, height),
                key.spatial,
            )
            .map_err(str::to_owned)?;
            Ok(read_texture_rgba16f(&gpu, &matte, width, height))
        } else if let Some((ops, index)) = legacy_key {
            let matte = photonic_render::qualifier_matte_gpu(
                gpu.device(),
                gpu.queue(),
                &texture,
                &ops,
                index,
                (width, height),
            )
            .ok_or("selected corrector is not a qualifier")?;
            Ok(read_texture_rgba16f(&gpu, &matte, width, height))
        } else {
            Ok(read_texture_rgba16f(&gpu, &texture, width, height))
        }
    })
    .await
    .map_err(|error| ToolResult::error(format!("inspection readback failed: {error}")))?
    .map_err(|error| err_code("QualifierReadbackFailed", error))?;
    let display_pixels = if matches!(mode, ScopeReadbackMode::ProgramOutput) {
        let gpu = bridge.engine().gpu().clone();
        let output = frame.texture.clone();
        Some(
            tokio::task::spawn_blocking(move || read_texture_rgba16f(&gpu, &output, width, height))
                .await
                .map_err(|e| err_code("NativeOutputReadbackFailed", e.to_string()))?,
        )
    } else {
        None
    };
    Ok(ScopeMeasurement {
        display_pixels,
        content_hash: frame.content_hash.0,
        pixels,
        width,
        height,
        tap: frame.scope_tap_point,
        time: frame.time,
        revision: frame.doc_revision,
        generation: frame.snapshot_generation,
        diagnostics: frame.grading_errors.clone(),
        encoding: frame.scope_tap_encoding.expect("validated tap encoding"),
    })
}

fn validate_scope_tap_encoding(
    encoding: Option<photonic_video::graph::ir::FrameColorEncoding>,
) -> Result<(), ToolResult> {
    use photonic_video::graph::ir::FrameColorEncoding;
    match encoding {
        Some(
            FrameColorEncoding::LegacyLinearRec709
            | FrameColorEncoding::SrgbDisplay
            | FrameColorEncoding::SceneLinearAcescg,
        ) => Ok(()),
        Some(other) => Err(err_code(
            "ScopeColorInterpretationUnavailable",
            format!("the {other:?} tap needs a qualified color-specific scope scale"),
        )),
        None => Err(err_code(
            "ScopeColorInterpretationUnavailable",
            "the scope tap's color interpretation is unresolved",
        )),
    }
}

