    #[tokio::test]
    async fn track_composite_mcp_edits_are_atomic_locked_and_serializable() {
        let state = test_state();
        let (seq, track) = create_seq_and_track(&state, "video").await;
        Box::pin(graph_authoring_edit_roundtrip(
            &state,
            "set_track_prop",
            json!({"track_id":track,"blend":"soft_light","opacity":0.375}),
        ))
        .await;
        let before = serde_json::to_value(&*state.document.lock().await).unwrap();
        let revision = state.history.lock().await.revision();
        assert_ne!(
            call(
                &state,
                "set_track_prop",
                json!({"track_id":track,"blend":"soft_light","opacity":0.375})
            )
            .await
            .is_error,
            Some(true)
        );
        assert_eq!(state.history.lock().await.revision(), revision);
        for value in [-0.01, 1.01] {
            assert_eq!(
                call(
                    &state,
                    "set_track_prop",
                    json!({"track_id":track,"name":"must not change","opacity":value})
                )
                .await
                .is_error,
                Some(true)
            );
            assert_eq!(
                serde_json::to_value(&*state.document.lock().await).unwrap(),
                before
            );
        }
        assert_ne!(
            call(
                &state,
                "set_track_prop",
                json!({"track_id":track,"locked":true})
            )
            .await
            .is_error,
            Some(true)
        );
        let locked = serde_json::to_value(&*state.document.lock().await).unwrap();
        let revision = state.history.lock().await.revision();
        assert_eq!(
            call(
                &state,
                "set_track_prop",
                json!({"track_id":track,"locked":false,"blend":"screen"})
            )
            .await
            .is_error,
            Some(true)
        );
        assert_eq!(
            serde_json::to_value(&*state.document.lock().await).unwrap(),
            locked
        );
        assert_eq!(state.history.lock().await.revision(), revision);
        let audio = create_track(&state, &seq, "audio").await;
        assert_eq!(
            call(
                &state,
                "set_track_prop",
                json!({"track_id":audio,"opacity":1.0})
            )
            .await
            .is_error,
            Some(true)
        );
        let doc = state.document.lock().await;
        let reloaded: photonic_core::Document =
            serde_json::from_str(&doc.to_json().unwrap()).unwrap();
        assert_eq!(
            serde_json::to_value(reloaded.timeline).unwrap(),
            serde_json::to_value(&doc.timeline).unwrap()
        );
    }

    // ── Tool family: clip edit ops ────────────────────────────────────────────

    #[tokio::test]
    async fn family_clip_edit_ops() {
        let state = test_state();
        let (seq_id, track_id) = create_seq_and_track(&state, "video").await;

        let clip_a = insert_solid_clip(&state, &track_id, 0, 1000).await;
        let clip_b = insert_solid_clip(&state, &track_id, 1000, 1000).await;

        let r = call(
            &state,
            "roll_edit",
            json!({ "clip_id_a": clip_a, "clip_id_b": clip_b, "delta_ticks": 100 }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "roll_edit: {r:?}");

        let r = call(
            &state,
            "move_clip",
            json!({ "clip_id": clip_a, "new_start_ticks": 5000 }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "move_clip: {r:?}");

        // Cross-track move.
        let other_track = create_track(&state, &seq_id, "video").await;
        let r = call(
            &state,
            "move_clip",
            json!({ "clip_id": clip_a, "new_start_ticks": 6000, "new_track_id": other_track }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "cross-track move_clip: {r:?}");
        let r = call(&state, "list_clips", json!({ "track_id": other_track })).await;
        let clips_on_dest = data(&r)["clips"].as_array().cloned().unwrap_or_default();
        assert_eq!(
            clips_on_dest.len(),
            1,
            "clip should have landed on the destination track: {clips_on_dest:?}"
        );

        let r = call(
            &state,
            "trim_clip",
            json!({ "clip_id": clip_b, "edge": "out", "new_ticks": 1500 }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "trim_clip: {r:?}");

        let r = call(
            &state,
            "slip_clip",
            json!({ "clip_id": clip_b, "delta_ticks": 10 }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "slip_clip: {r:?}");

        // Fresh isolated pair for slide_clip so it doesn't interact with clip_a/clip_b's post-roll state.
        let track2 = create_track(&state, &seq_id, "video").await;
        let clip_c = insert_solid_clip(&state, &track2, 0, 1000).await;
        let clip_d = insert_solid_clip(&state, &track2, 1000, 1000).await;
        let r = call(
            &state,
            "slide_clip",
            json!({ "clip_id": clip_d, "delta_ticks": 50 }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "slide_clip: {r:?}");

        let r = call(
            &state,
            "remove_clip",
            json!({ "clip_id": clip_c, "ripple": true }),
        )
        .await;
        assert_ne!(r.is_error, Some(true), "remove_clip ripple: {r:?}");
    }

