                for (i, path) in paths.iter().enumerate() {
                    for (at, value) in [(0, values[i]), (2 * tpf, target[i])] {
                        keys.push(json!({"target":"clip_effect","clip_id":cid,"effect_index":0,"path":path,"at_ticks":at,"value":{"t":"float","v":value},"interp":{"kind":"linear"}}));
                    }
                }
